comms.text:
@1 וַחֲיָא יַעֲקֹב בְּאַרְעָא דְמִצְרַיִם שְׁבַע עֶשְׂרֵי שְׁנִין וַהֲווֹ יוֹמֵי יַעֲקֹב שְׁנֵי חַיוֹהִי מְאָה וְאַרְבְּעִין וּשְׁבַע שְׁנִין:
@2 וּקְרִיבוּ יוֹמֵי יִשְׂרָאֵל לִמְמַת וּקְרָא לִבְרֵהּ לְיוֹסֵף וַאֲמַר לֵהּ אִם כְּעַן אַשְׁכָּחִית רַחֲמִין בְּעֵינָיךְ שַׁוִּי כְעַן יְדָךְ תְּחוֹת יַרְכִּי וְתַעְבֵּד עִמִּי טִיבוּ וּקְשׁוֹט לָא כְעַן תִּקְבְּרִנַּנִי בְּמִצְרַיִם:
@3 וְאִשְׁכּוּב עִם אֲבָהָתַי וְתִטְּלִנַנִּי מִמִּצְרַיִם וְתִקְבְּרִנַנִּי בִּקְבֻרְתְּהוֹן וַאֲמַר אֲנָא אֶעְבַּד כְּפִתְגָּמָךְ:
@4 וַאֲמַר קַיֵּם לִי וְקַיִים לֵהּ וּסְגִיד יִשְׂרָאֵל עַל רֵישׁ עַרְסָא:
@5 וַהֲוָה בָּתַר פִּתְגָּמַיָּא הָאִלֵּין וַאֲמַר לְיוֹסֵף הָא אֲבוּךְ שְׁכִיב מְרָע וּדְבַר יָת תְּרֵין בְּנוֹהִי עִמֵּהּ יָת מְנַשֶּׁה וְיָת אֶפְרָיִם:
@6 וְחַוִּי לְיַעֲקֹב וַאֲמַר הָא בְּרָךְ יוֹסֵף אֲתָא לְוָתָךְ וְאִתַּקַף יִשְׂרָאֵל וִיתֵיב עַל עַרְסָא:
@7 וַאֲמַר יַעֲקֹב לְיוֹסֵף אֵל שַׁדַּי אִתְגְּלִי לִי בְלוּז בְּאַרְעָא דִכְנָעַן וּבָרִיךְ יָתִי:
@8 וַאֲמַר לִי הָא אֲנָא מַפְשִׁינָךְ וְאַסְגִּנָּךְ וְאֶתְּנִנָּךְ לְכִנְשַׁת שִׁבְטִין וְאֶתֵּן יָת אַרְעָא הָדָא לִבְנָיךְ בַּתְרָךְ אַחֲסָנַת עֲלָם:
@9 וּכְעַן תְּרֵין בְּנָיךְ דְּאִתְיְלִידוּ לָךְ בְּאַרְעָא דְמִצְרַיִם עַד מֵיתִי לְוָתָךְ לְמִצְרַיִם דִּילִי אִנּוּן אֶפְרַיִם וּמְנַשֶּׁה כִּרְאוּבֵן וְשִׁמְעוֹן יְהוֹן קֳדָמָי:
@10 וּבְנָיךְ דִּי תוֹלִיד בַּתְרֵיהוֹן דִּילָךְ יְהוֹן עַל שׁוּם אֲחוּהוֹן יִתְקְרוּן בְּאַחֲסַנְתְּהוֹן:
@11 וַאֲנָא בְּמֵיתִי מִפַּדָן מִיתַת עָלַי רָחֵל בְּאַרְעָא דִּכְנַעַן בְּאָרְחָא בְּעוֹד כְּרוּבָא דְאַרְעָא לְמֵיעַל לְאֶפְרָת וּקְבָרִתַּהּ תַּמָּן בְּאֹרַח אֶפְרָת הִיא בֵּית לָחֶם:
@12 וַחֲזָא יִשְׂרָאֵל יָת בְּנֵי יוֹסֵף וַאֲמַר מַן אִלֵּין:
@13 וַאֲמַר יוֹסֵף לַאֲבוּהִי בְּנַי אִנּוּן דִּי יְהַב לִי יְיָ הָכָא וַאֲמַר קָרֵבִנּוּן כְּעַן לְוָתִי וְאֵבָרֵכִנּוּן:
@14 וְעֵינֵי יִשְׂרָאֵל יְקָרָן מִסֵּיבוּ לָא יִכּוּל לְמֶחֱזֵי וְקָרִיב יָתְהוֹן לְוָתֵהּ וְנַשִּׁיק לְהוֹן וְגַפִּיף לְהוֹן:
@15 וַאֲמַר יִשְׂרָאֵל לְיוֹסֵף לְמֶחֱזֵי אַפָיךְ לָא סְבָרִית וְהָא אַחֲזִי יָתִי יְיָ אַף יָת בְּנָיךְ:
@16 וְאַפֵּיק יוֹסֵף יָתְהוֹן מִן קֳדָמוֹהִי וּסְגִיד עַל אַפּוֹהִי עַל אַרְעָא:
@17 וּדְבַר יוֹסֵף יָת תַּרְוֵיהוֹן יָת אֶפְרַיִם בִּימִינֵהּ מִשְׂמָאלָא דְיִשְׂרָאֵל וְיָת מְנַשֶּׁה בִשְׂמָאלֵהּ מִימִינָא דְיִשְׂרָאֵל וְקָרֵיב לְוָתֵהּ:
@18 וְאוֹשִׁיט יִשְׂרָאֵל יָת יְמִינֵהּ וְשַׁוִּי עַל רֵישָׁא דְאֶפְרַיִם וְהוּא זְעֵירָא וְיָת שְׂמָאלֵהּ עַל רֵישָׁא דִּמְנַשֶּׁה אַחְכִּמִינּוּן לִידוֹהִי אֲרֵי מְנַשֶּׁה בּוּכְרָא:
@19 וּבְרִיךְ יָת יוֹסֵף וַאֲמָר יְיָ דִי פְלָחוּ אֲבָהָתַי קֳדָמוֹהִי אַבְרָהָם וְיִצְחָק יְיָ דְזַן יָתִי מִדְאִיתָנִי עַד יוֹמָא הָדֵין:
@20 מַלְאָכָא דִי פְרַק יָתִי מִכָּל בִּישָׁא יְבָרֵךְ יָת עוּלֵמַיָּא וְיִתְקְרֵי בְהוֹן שְׁמִי וְשׁוּם אֲבָהָתַי אַבְרָהָם וְיִצְחָק וּכְנוּנֵי יַמָּא יִסְגוּן בְּגוֹ בְנֵי אֱנָשָׁא עַל אַרְעָא:
@21 וַחֲזָא יוֹסֵף אֲרֵי שַׁוִּי אָבוּהִי יַד יְמִינֵהּ עַל רֵישָׁא דְאֶפְרַיִם וּבְאֵישׁ בְּעֵינוֹהִי וְסָעֵד יְדָא דְאָבוּהִי לְאַעֲדָאָה יָתַהּ מֵעַל רֵישָׁא דְאֶפְרַיִם לְאַנָחוּתַהּ עַל רֵישָׁא דִמְנַשֶּׁה:
@22 וַאֲמַר יוֹסֵף לְאָבוּהִי לָא כֵן אַבָּא אֲרֵי דֵין בּוּכְרָא שַׁו יְמִינָךְ עַל רֵישֵׁהּ:
@23 וְסָרֵיב אָבוּהִי וַאֲמַר יְדַעְנָא בְרִי יְדַעְנָא אַף הוּא יְהֵי לְעַמָּא וְאַף הוּא יִסְגֵּי וּבְרַם אָחוּהִי זְעִירָא יִסְגֵּי מִנֵּהּ וּבְנוֹהִי יְהוֹן שַׁלִּיטִין בְּעַמְמַיָּא:
@24 וּבְרֵיכִנּוּן בְּיוֹמָא הַהוּא לְמֵימַר בָּךְ יְבָרֵךְ יִשְׂרָאֵל לְמֵימַר יְשַׁוִּינָךְ יְיָ כְּאֶפְרַיִם וְכִמְנַשֶּׁה וְשַׁוִּי יָת אֶפְרַיִם קֳדָם מְנַשֶּׁה:
@25 וַאֲמַר יִשְׂרָאֵל לְיוֹסֵף הָא אֲנָא מָאִית וִיהֵי מֵימְרָא דַיְיָ בְּסַעְדְכוֹן וְיָתֵיב יָתְכוֹן לְאַרְעָא דַאֲבָהַתְכוֹן:
@26 וַאֲנָא יְהָבִית לָךְ חוּלַק חַד יַתִּיר עַל אַחָיךְ דִּי נְסֵיבִית מִידָא דֶאֱמוֹרָאָה בִּצְלוֹתִי וּבְבָעוּתִי:
@27 וּקְרָא יַעֲקֹב לִבְנוֹהִי וַאֲמַר אִתְכַּנָשׁוּ וַאֲחַוֵּי לְכוֹן יָת דִּי יְעָרַע יָתְכוֹן בְּסוֹף יוֹמַיָּא:
@28 אִתְכַּנָּשׁוּ וּשְׁמָעוּ בְּנֵי יַעֲקֹב וְקַבִּילוּ אוּלְפַן מִן יִשְׂרָאֵל אֲבוּכוֹן:
@29 רְאוּבֵן בּוּכְרִי אַתְּ חֵילִי וְרֵישׁ תָּקְפִּי לָךְ הֲוָה חָזֵי לְמִסַּב תְּלָתָא חוּלָקִין בְּכֵירוּתָא כְּהֻנְתָּא וּמַלְכוּתָא:
@30 עַל דַאֲזַלְתָּא לָקֳבֵל אַפָּיךְ הָא כְמַיָּא בְּרַם לָא אַהֲנֵיתָא חוֹלָק יַתִּיר לָא תִסַּב אֲרֵי סְלֶקְתָּא בֵּית מִשְׁכָּבֵי אָבוּךְ בְּכֵן אֲחֶלְתָּא לְשִׁוּוּיִי בְּרִי סְלֶקְתָּא:
@31 שִׁמְעוֹן וְלֵוִי אַחִין גַּבְרִין גִּבָּרִין בְּאַרַע תּוֹתָבוּתְהוֹן עֲבָדוּ גְּבוּרָא:
@32 בְּרָזְהוֹן לָא הֲוַת נַפְשִׁי בְּאִתְכַּנְשֵׁהוֹן לִמְהַךְ לָא נְחָתִית מִן יְקָרִי אֲרֵי בְרָגְזְהוֹן קְטָלוּ קְטוֹל וּבִרְעוּתְהוֹן תַּרָעוּ שׁוּר סַנְּאָה:
@33 לִיט רָגְזְהוֹן אֲרֵי תַקִיף וְחֵמַתְהוֹן אֲרֵי קַשְׁיָא אֲפַלְגִנוּן בְּיַעֲקֹב וְאֵבַדָרִנוּן בְּיִשְׂרָאֵל:
@34 יְהוּדָה אַתְּ אוֹדֵיתָא וְלָא בְהֵיתְתָא בָּךְ יוֹדוּן אַחָיךְ יְדָךְ תִּתְקֵף עַל בַּעֲלֵי דְבָבָךְ יִתְבַּדְרוּן סַנְאָךְ יְהוֹן מְחַזְרִין קְדַּל קֳדָמָךְ וִיְהוֹן מְקַדְמִין לְמִשְׁאַל בִּשְׁלָמָךְ בְּנֵי אָבוּךְ:
@35 שִׁלְטוֹן יְהֵי בְשֵׁרוּיָא וּבְסוֹפָא יִתְרַבָּא מַלְכָּא מִדְבֵית יְהוּדָה אֲרֵי מִדִין קַטְלָא בְּרִי נַפְשָׁךְ סְלֶקְתָּא יְנוּחַ יִשְׁרֵי בִתְקוֹף כְּאַרְיָא וּכְלֵיתָא וְלֵית מַלְכוּ דִתְזַעְזְעִנֵהּ:
@36 לָא יַעֲדֵי עָבֵד שָׁלְטַן מִדְבֵית יְהוּדָה וְסַפְרָא מִבְּנֵי בְנוֹהִי עַד עָלְמָא עַד דְיֵיתֵי מְשִׁיחָא דְדִילֵהּ הִיא מַלְכוּתָא וְלֵהּ יִשְׁתַּמְעוּן עַמְמַיָּא:
@37 יַסְחַר יִשְׂרָאֵל לְקַרְתֵּהּ עַמָּא יִבְנוּן הֵיכְלֵהּ יְהוֹן צַדִּיקַיָּא סְחוֹר סְחוֹר לֵהּ וְעָבְדֵי אוֹרַיְתָא בְּאוּלְפַן עִמֵּהּ יְהֵי אַרְגְוָן טַב לְבוּשׁוֹהִי כְּסוּתֵהּ מֵילָא מֵילָא צְבַע זְהוֹרִי:וצִבְעוֹנִין:
@38 ??? יְסַמְקוּן טּוּרוֹהִי בְּכַרְמוֹהִי יְטוּפוּן נַעֲווֹהִי בַּחֲמָר יְחַוְרָן בִּקְעֲתֵהּ בְּעִיבוּר וּבְעֶדְרֵי עָנָא:
@39 זְבוּלֻן עַל סְפַר יַמְמַיָּא יִשְׁרֵי וְהוּא יְכַבֵּשׁ מְחוֹזִין בִּסְפִינַן וְטוּב יַמָּא יֵיכוּל וּתְחוּמֵהּ יְהֵי מָטֵי עַל צִידוֹן:
@40 יִשָּׂשׂכָר עַתִּיר בְּנִכְסִין וְאַחֲסַנְתֵּהּ בֵּין תְּחוּמַיָּא:
@41 וַחֲזָא חוּלָקָא אֲרֵי טַב וְיָת אַרְעָא אֲרֵי מְעַבְּדָא פֵירִין וִיכַבֵּשׁ מָחוֹזֵי עַמְמַיָּא וִישֵׁיצֵי יָת דַּיָרֵיהוֹן וּדְאִשְׁתַּאֲרוּן בְּהוֹן יְהוֹן לֵהּ פַּלְחִין וּמַסְּקֵי מַסִּין:
@42 מִדְּבֵית דָּן יִתְבְּחַר וִיקוּם גַּבְרָא בְּיוֹמוֹהִי יִתְפְּרֵק עַמֵּהּ וּבִשְׁנוֹהִי יְנוּחוּן כַּחֲדָא שִׁבְטַּיָּא דְיִשְׂרָאֵל:
@43 יְהֵי גַבְרָא דְיִתְבְּחַר וִיקוּם מִדְּבֵית דָּן אֵימְתֵהּ תִּתְרְמֵי עַל עַמְמַיָּא וּמְחָתֵהּ תִּתְקֵף בִּפְלִשְׁתָּאֵי כְּחִיוֵי חוּרְמָן יִשְׁרֵי עַל אָרְחָא וּכְפִתְנָא יִכְמוֹן עַל שְׁבִילָא יְקַטֵּיל גִּבָּרֵי מַשִׁרְיַת פְּלִשְׁתָּאֵי פָּרָשִׁין עִם רַגְלָאִין יְעַקֵר סוּסָוָן וּרְתִכִּין וִימַגֵּר רוֹכְבֵיהוֹן לַאֲחוֹרָא:
@44 לְפוּרְקָנָךְ סַבָּרִית יְיָ:
@45 מִדְבֵית גָד מַשִׁרְיַת מְזַיְנִין כַּד יַעַבְרוּן יָת יַרְדְנָא קֳדָם אֲחֵיהוֹן לִקְרָבָא וּבְנִכְסִין סַגִּיאִין יְתוּבוּן לְאַרְעֲהוֹן:
@46 דְאָשֵׁר טָבָא אַרְעֵהּ וְהוּא מְרַבְיָא בְּתַפְנוּקֵי מַלְכִין:
@47 נַפְתָּלִי בְּאַרַע טָבָא יִתְרְמֵי עַדְבֵהּ וְאַחְסַנְתֵּהּ תְּהֵי מְעַבְּדָא פֵירִין יְהוֹן מוֹדַן וּמְבָרְכִין עֲלֵיהוֹן:
@48 בְּרִי דְיִסְגֵּי יוֹסֵף בְּרִי דְיִתְבָּרַךְ כְּגֹפֶן דִּנְצִב עַל עֵינָא דְמַיָּא תְּרֵין שִׁבְטִין יִפְּקוּן מִבְּנוֹהִי יְקַבְּלוּן חוּלָקָא וְאַחֲסַנְתָּא:
@49 וְאִתְמַרְרוּ יָתֵהּ וְנַקְמוֹהִי וְאָעִיקוּ לֵהּ גֻבְרִין גִּבָּרִין בַּעֲלֵי פַלְגוּתָא:
@50 וְתָבַת בְּהוֹן נְבִיאוּתֵהּ עַל דְּקַיֵּם אוֹרַיְתָא בְּסִתְרָא וְשַׁוִּי בְתוּקְפָא רוֹחֲצָנֵהּ בְּכֵן יִתְרְמָא דְהַב עַל דְּרָעוֹהִי וְאַחֲסִין מַלְכוּתָא וּתְקֵיף דָּא הֲוַת לֵהּ מִן קֳדָם אֵל תַּקִיפָא דְיַעֲקֹב דִּי בְמֵימְרֵהּ זַן אֲבָהָן וּבְנִין זַרְעָא דְיִשְׂרָאֵל:
@51 מֵימַר אֱלָהָא דְאָבוּךְ יְהֵי בְסַעְדָךְ וְיָת שַׁדַּי וִיבָרְכִנָּךְ בִּרְכַן דְּנַחֲתָן מִטַּלָּא דִשְׁמַיָּא מִלְעֵלָא בִּרְכַן דְנַגְדַן מִמַעֲמַקֵי אַרְעָא מִלְרָע בִּרְכְּתָא דְאָבוּךְ וּדְאִמָּךְ:
@52 בִּרְכְּתָא דְאָבוּךְ יִתּוֹסְפָן עַל בִּרְכְּתָא דִילִי בָּרִיכוּ אֲבָהָתַי דַחֲמִידוּ לְהֶן רַבְרְבַיָּא דְמִן עָלְמָא יֶהֶוְיַן כָּל אִלֵּין לְרֵישָׁא דְיוֹסֵף וּלְגַבְרָא פָּרִישָׁא דַאֲחוֹהִי:
@53 בִּנְיָמִין בְּאַרְעֵהּ תִּשְׁרֵי שְׁכִנְתָּא וּבְאַחֲסַנְתֵּהּ יִתְבְּנֵי מַקְדְשָׁא בְּצַפְרָא וּבְפַנְיָא יְהוֹן מְקָרְבִין כַּהֲנַיָּא קָרְבָּנָא וּבְעִדַּן רַמְשָׁא יְהוֹן מְפַלְגִין מוֹתַר חוּלְקְהוֹן מִשְׁאַר קָדְשַׁיָּא:
@54 כָּל אִלֵּין שִׁבְטַיָּא דְיִשְׂרָאֵל תְּרֵין עֲסַר וְדָא דְמַלֵּיל לְהוֹן אֲבוּהוֹן וּבָרִיךְ יָתְהוֹן גְבַר דִּי כְבִרְכְּתֵהּ בָּרֵךְ יָתְהוֹן:
@55 וּפַקֵד יָתְהוֹן וַאֲמַר לְהוֹן אֲנָא מִתְכְּנֵשׁ לְעַמִּי קְבָרוּ יָתִי לְוַת אֲבָהָתִי בִּמְעַרְתָּא דִי בַחֲקַל עֶפְרוֹן חִתָּאָה:
@56 בִּמְעַרְתָּא דִי בַחֲקַל כָּפֶלְתָּא דִי עַל אַפֵּי מַמְרֵא בְּאַרְעָא דִכְנָעַן דִי זְבַן אַבְרָהָם יָת חַקְלָא מִן עֶפְרֹן חִתָּאָה לְאַחֲסָנַת קְבוּרָא:
@57 תַּמָּן קְבָרוּ יָת אַבְרָהָם וְיָת שָׂרָה אִתְּתֵהּ תַּמָּן קְבָרוּ יָת יִצְחָק וְיָת רִבְקָה אִתְּתֵהּ וְתַמָּן קְבָרִית יָת לֵאָה:
@58 זְבִינֵי חַקְלָא וּמְעַרְתָּא דִי בֵהּ מִן בְּנֵי חִתָּאָהּ:
@59 וְשֵׁיצֵי יַעֲקֹב לְפַקָּדָא יָת בְּנוֹהִי וּכְנַשׁ רַגְלוֹהִי לְעַרְסָא וְאִתְנְגִיד וְאִתְכְּנִישׁ לְעַמֵּהּ:
@60 וּנְפַל יוֹסֵף עַל אַפֵּי אָבוּהִי וּבְכָא עֲלוֹהִי וּנְשַׁק לֵהּ:
@61 וּפַקֵּיד יוֹסֵף יָת עַבְדוֹהִי יָת אַסְוָתָא לְמֶחְנַט יָת אָבוּהִי וְחָנְטוּ אַסְוָתָא יָת יִשְׂרָאֵל:
@62 וּשְׁלִימוּ לֵהּ אַרְבְּעִין יוֹמִין אֲרֵי כֵּן שְׁלִימוּ יוֹמֵי חֲנִיטַיָּא וּבְכוֹ יָתֵהּ מִצְרָאֵי שַׁבְעִין יוֹמִין:
@63 וַעֲבָרוּ יוֹמֵי בְכִיתֵהּ וּמַלִיל יוֹסֵף עִם בֵּית פַּרְעֹה לְמֵימָר אִם כְּעַן אַשְׁכָּחִית רַחֲמִין בְּעֵינֵיכוֹן מַלִּילוּ כְעַן קֳדָם פַּרְעֹה לְמֵימָר:
@64 אַבָּא קַיֵּים עָלַי לְמֵימָר הָא אֲנָא מָאִית בְּקִבְרִי דְאַתְקֵנִית לִי בְּאַרְעָא דִכְנָעַן תַּמָּן תִּקְבְּרִנָנִי וּכְעַן אֶסַּק כְּעַן וְאֶקְבַּר יָת אַבָּא וְאֵ יתוּב:
@65 וַאֲמַר פַּרְעֹה סַק וּקְבוֹר יָת אֲבוּךְ כְּמָא דְקַיֵּים עֲלָךְ:
@66 וּסְלֵיק יוֹסֵף לְמִקְבַּר יָת אָבוּהִי וּסְלִיקוּ עִמֵּהּ כָּל עַבְדֵי פַרְעֹה סָבֵי בֵיתֵהּ וְכֹל סָבֵי אַרְעָא דְמִצְרָיִם:
@67 וְכֹל בֵּית יוֹסֵף וַאֲחוֹהִי וּבֵית אָבוּהִי לְחוֹד טַפְלְהוֹן וְעָנְהוֹן וְתוֹרֵיהוֹן שְׁבָקוּ בְּאַרְעָא דְגשֶׁן:
@68 וּסְלִיקוּ עִמֵּהּ אַף רְתִכִּין אַף פָּרָשִׁין וַהֲוָה מַשְׁרִיתָא סַגִּיאָה לַחֲדָא:
@69 וַאֲתוֹ עַד בֵּית אִדְרֵי דְאָטָד דִּי בְּעִבְרָא דְיַרְדְנָא וּסְפָדוּ תַמָּן מִסְפֵּד רַב וְתַקִּיף לַחֲדָא וְעָבַד לַאֲבוּהִי אֶבְלָא שַׁבְעָא יוֹמִין:
@70 וַחֲזָא יָתֵב אַרְעָא כְנַעֲנָאָה יָת אֶבְלָא בְּבֵית אִדְרֵי דְאָטָד וַאֲמָרוּ אָבֵל תַּקִּיף דֵּין לְמִצְרָאֵי עַל כֵּן קְרָא שְׁמַהּ אָבֵל מִצְרַיִם דִּי בְּעִבְרָא דְיַרְדְנָא:
@71 וַעֲבָדוּ בְּנוֹהִי לֵהּ כֵּן כְּמָא דִי פַּקֵדִנּוּן:
@72 וּנְטָלוּ יָתֵהּ בְּנוֹהִי לְאַרְעָא דִכְנַעַן וּקְבָרוּ יָתֵהּ בִּמְעָרַת חֲקַל כָּפֶלְתָּא דִי זְבַן אַבְרָהָם יָת חַקְלָא לְאַחֲסָנַת קְבוּרָא מִן עֶפְרֹן חִתָּאָה עַל אַפֵּי מַמְרֵא:
@73 וְתַב יוֹסֵף לְמִצְרַיִם הוּא וַאֲחוֹהִי וְכָל דִּסְלִיקוּ עִמֵּהּ לְמִקְבַּר יָת אָבוּהִי בָּתַר דִּקְבַר יָת אָבוּהִי:
@74 וַחֲזוֹ אֲחֵי יוֹסֵף אֲרֵי מִית אֲבוּהוֹן וַאֲמָרוּ דִּלְמָא יִטַּר לָנָא דְבָבוּ יוֹסֵף וְאֲתָבָא יָתֵיב לָנָא יָת כָּל בִּישְׁתָא דִי גְמַלְנָא יָתֵהּ:
@75 וּפַקִידוּ לְוַת יוֹסֵף לְמֵימָר אָבוּךְ פַּקֵּד קֳדָם מוֹתֵהּ לְמֵימָר:
@76 כְּדֵין תֵּימְרוּן לְיוֹסֵף בְּבָעוּ שְׁבוֹק כְּעַן לְחוֹבָא אַחָיךְ וְלַחֲטָאֵהוֹן אֲרֵי בִישְׁתָא גְמָלוּךְ וּכְעַן שְׁבוֹק כְּעַן לְחוֹבָא עַבְדֵי אֱלָהָא דְאָבוּךְ וּבְכָא יוֹסֵף בְּמַלָלוּתְהוֹן עִמֵּהּ:
@77 וַאֲזָלוּ אַף אֲחוֹהִי וּנְפָלוּ קֳדָמוֹהִי וַאֲמָרוּ הָא אֲנַחְנָא לָךְ לְעַבְדִין:
@78 וַאֲמַר לְהוֹן יוֹסֵף לָא תִדַחֲלוּן אֲרֵי דַחֲלָא דַּיְיָ אֲנָא:
@79 וְאַתּוּן חֲשַׁבְתּוּן עֲלַי בִּישָׁא מִן קֳדָם יְיָ אִתְחַשְׁבַת לְטָבָא בְּדִיל לְמֶעְבַּד כְּיוֹמָא הָדֵין לְקַיָּמָא עַם סַגִּי:
@80 וּכְעַן לָא תִדַחֲלוּן אֲנָא אֵזוּן יָתְכוֹן וְיָת טַפְלְכוֹן וְנַחֵם יָתְהוֹן וּמַלֵּיל תַּנְחוּמִין עַל לִבְּהוֹן:
@81 וִיתֵיב יוֹסֵף בְּמִצְרַיִם הוּא וּבֵית אָבוּהִי וַחֲיָא יוֹסֵף מְאָה וַעֲסַר שְׁנִין:
@82 וַחֲזָא יוֹסֵף לְאֶפְרַיִם בְּנִין תְּלִיתָאִין אַף בְּנֵי מָכִיר בַּר מְנַשֶּׁה אִתְיְלִידוּ וְרַבִּי יוֹסֵף:
@83 וַאֲמַר יוֹסֵף לַאֲחוֹהִי אֲנָא מָאִית וַיְיָ מִדְכַּר דְּכִיר יָתְכוֹן וְיִסַק יָתְכוֹן מִן אַרְעָא הָדָא לְאַרְעָא דִי קַיִים לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:
@84 וְאוֹמֵי יוֹסֵף יָת בְּנֵי יִשְׂרָאֵל לְמֵימָר מִדְכַּר דְּכִיר יְיָ יָתְכוֹן וְתַסְקוּן יָת גַּרְמַי מִכָּא:
@85 וּמִית יוֹסֵף בַּר מְאָה וַעֲסַר שְׁנִין וַחֲנָטוּ יָתֵהּ וְשָׂמוּהִי בָאֳרוֹנָא בְּמִצְרָיִם: חזק:

@1 **ויחי יעקב.** למה פרשה זו סתומה, לפי שכיון שנפטר יעקב אבינו נסתמו עיניהם ולבם של ישראל מצרת השעבוד שהתחילו לשעבדם. דבר אחר שבקש לגלות את הקץ לבניו ונסתם ממנו:
@2 **ויקרבו ימי ישראל למות.** כל מי שנאמר בו קריבה למות לא הגיע לימי אבותיו. [יצחק חי מאה ושמונים ויעקב מאה ארבעים ושבע. בדוד נאמר קריבה, אביו חי ארבע מאות שנים והוא חי שבעים]: **ויקרא לבנו ליוסף.** למי שהיה יכולת בידו לעשות: **שים נא ידך.** והשבע: **חסד ואמת.** חסד שעושין עם המתים הוא חסד של אמת, שאינו מצפה לתשלום גמול: **אל נא תקברני במצרים.** סופה להיות עפרה כנים ומרחשין תחת גופי ושאין מתי חוצה לארץ חיים אלא בצער גלגול מחלות, ושלא יעשוני מצרים עבודה זרה:
@3 **ושכבתי עם אבתי.** וי''ו זו מחבר למעלה לתחלת המקרא (פסוק כט) שים נא ידך תחת ירכי והשבע לי, ואני סופי לשכב עם אבותי, ואתה תשאני ממצרים. ואין לומר ושכבתי עם אבותי, השכיבני עם אבותי במערה, שהרי כתיב אחריו ונשאתני ממצרים וקברתני בקברתם. ועוד, מצינו בכמה מקומות לשון שכיבה עם אבותיו היא הגויעה, ולא הקבורה, כמו (מ''א ב י) וישכב דוד עם אבותיו, ואחר כך ויקבר בעיר דוד:
@4 **וישתחו ישראל.** תעלא בעדניה סגיד ליה: **על ראש המטה.** הפך עצמו לצד השכינה, מכאן אמרו שהשכינה למעלה מראשותיו של חולה. דבר אחר על ראש המטה, על שהיתה מטתו שלמה שאין בה רשע, שהרי יוסף מלך הוא, ועוד שנשבה לבין הגוים, והרי הוא עומד בצדקו:
@5 **ויאמר ליוסף.** אחד מן המגידים, והרי זה מקרא קצר. ויש אומרים אפרים היה רגיל לפני יעקב בתלמוד, וכשחלה יעקב בארץ גושן, הלך אפרים אצל אביו למצרים והגיד לו: **ויקח את שני בניו עמו.** כדי שיברכם יעקב לפני מותו:
@6 **ויגד.** המגיד ליעקב, ולא פרש מי, והרבה מקראות קצרי לשון: **ויתחזק ישראל.** אמר אף על פי שהוא בני, מלך הוא ואחלוק לו כבוד. מכאן שחולקין כבוד למלכות, וכן משה חלק כבוד למלכות (שמות יא ח) וירדו כל עבדיך אלה אלי, וכן אליהו (מ''א יח מו) וישנס מתניו וגו' :
@8 **ונתתיך לקהל עמים.** בשרני שעתידים לצאת ממני עוד קהל ועמים ואף על פי שאמר לי (לעיל לה יא) גוי וקהל גוים, גוי אמר לי על בנימין, קהל גוים הרי שנים לבד מבנימין, ושוב לא נלד לי בן, למדני שעתיד אחד משבטי לחלק, ועתה אותה מתנה אני נותן לך:
@9 **הנולדים לך' עד באי אליך.** לפני בואי אליך, כלומר שנלדו משפרשת ממני עד שבאתי אצלך: **לי הם.** בחשבון שאר בני הם לטול חלק בארץ איש כנגדו:
@10 **ומולדתך** וגו' **.** אם תוליד עוד לא יהיו במנין בני אלא בתוך שבטי אפרים ומנשה יהיו נכללים, ולא יהא להם שם בשבטים לענין הנחלה, ואף על פי שנתחלקה הארץ למנין גלגלתם כדכתיב (במדבר כו נד) לרב תרבו נחלתו, וכל איש ואיש נטל בשוה חוץ מן הבכורות, מכל מקום לא נקראו שבטים אלא אלו [להטיל גורל הארץ למנין שמות השבטים, ונשיא לכל שבט ושבט. ודגלים לזה ולזה]:
@11 **ואני בבאי מפדן** וגו' **.** ואף על פי שאני מטריח עליך להוליכני להקבר בארץ כנען, ולא כך עשיתי לאמך, שהרי סמוך לבית לחם מתה: **כברת ארץ.** מדת ארץ, והם אלפים אמה כמדת תחום שבת, כדברי רבי משה הדרשן. ולא תאמר שעכבו עלי גשמים מלהוליכה ולקברה בחברון, עת הגריד היה, שהארץ חלולה ומנקבת ככברה: **ואקברה שם.** ולא הולכתיה אפלו לבית לחם להכניסה לארץ, וידעתי שיש בלבך עלי [תרעומת], אבל דע לך שעל פי הדבור קברתיה שם שתהא לעזרה לבניה כשיגלה אותם נבוזראדן, והיו עוברים דרך שם, יצאת רחל על קברה ובוכה ומבקשת עליהם רחמים, שנאמר (ירמיה לא יד) קול ברמה נשמע רחל מבכה על בניה וגו' , והקדוש ברוך הוא משיבה (ירמיה לא טו) יש שכר לפעלתך נאם ה' ושבו בנים לגבולם. ואונקלוס תרגם כרוב ארעא, כדי שעור חרישת יום [הארץ]. ואומר אני שהיה להם קצב שהיו קורין אותו כדי מחרשה אחת, קרואיד''א בלע''ז [מלוא מחרשה], כדאמרנן (בבא מציעא קז א) כרוב ותני, (יומא מג ב) כמה דמסיק תעלא מבי כרבא:
@12 **וירא ישראל את בני יוסף.** בקש לברכם ונסתלקה שכינה ממנו, לפי שעתיד ירבעם ואחאב לצאת מאפרים, ויהוא ובניו ממנשה: **ויאמר מי אלה.** מהיכן יצאו אלו שאינן ראויין לברכה:
@13 **בזה.** [הראה לו] שטר ארוסין ושטר כתבה, ובקש יוסף רחמים על הדבר ונחה עליו רוח הקדש: **ויאמר קחם נא אלי ואברכם.** זהו שאמר הכתוב (הושע יא ג) ואנכי תרגלתי לאפרים קחם על זרועתיו, תרגלתי רוחי ביעקב בשביל אפרים, עד שלקחן על זרועותיו:
@15 **לא פללתי.** לא מלאני לבי לחשב מחשבה שאראה פניך עוד. פללתי לשון מחשבה, כמו (ישעיה טז ג) הביאי עצה עשו פלילה:
@16 **ויוצא יוסף אתם.** לאחר שנשקם הוציאם יוסף מעם ברכיו כדי לישבם, זה לימין וזה לשמאל לסמוך ידיו עליהם ולברכם: **וישתחו לאפיו.** כשחזר לאחוריו מלפני אביו:
@17 **את אפרים בימינו משמאל ישראל.** הבא לקראת חברו ימינו כנגד שמאל חברו, וכיון שהוא הבכור מימן לברכה:
@18 **שכל את ידיו.** כתרגומו אחכמנון, בהשכל וחכמה השכיל את ידיו (לכך, ומדעת) , כי יודע היה כי מנשה הבכור, ואף על פי כן לא שת ימינו עליו:
@20 **המלאך הגאל אתי.** מלאך הרגיל להשתלח אלי בצרתי, כענין שנאמר (בראשית לא יא. יג) ויאמר אלי מלאך האלהים בחלום יעקב וגו' אנכי האל בית אל: **יברך את הנערים.** מנשה ואפרים: **וידגו.** כדגים הללו שפרים ורבים ואין עין הרע שולטת בהם:
@21 **ויתמך יד אביו.** הרימה מעל ראש בנו ותמכה בידו:
@23 **ידעתי בני ידעתי.** שהוא הבכור: **גם הוא יהיה לעם וגם הוא יגדל.** שעתיד גדעון לצאת ממנו שהקדוש ברוך הוא עושה נס על ידו: **ואולם אחיו הקטן יגדל ממנו.** שעתיד יהושע לצאת ממנו שינחיל את הארץ וילמד תורה לישראל: **וזרעו יהיה מלא הגוים.** כל העולם יתמלא בצאת שמעו כשיעמיד חמה בגבעון וירח בעמק אילון:
@24 **בך יברך ישראל.** הבא לברך את בניו, יברכם בברכתם ויאמר איש לבנו ישימך אלהים כאפרים וכמנשה: **וישם את אפרים.** בברכתו לפני מנשה, להקדימו בדגלים ובחנכת הנשיאים:
@26 **ואני נתתי לך.** לפי שאתה טורח להתעסק בקבורתי, וגם אני נתתי לך נחלה שתקבר בה, ואי זו, זו שכם, שנאמר (יהושע כד לב) ואת עצמות יוסף אשר העלו בני ישראל ממצרים קברו בשכם: **שכם אחד על אחיך.** שכם ממש, היא תהיה לך חלק אחד יתרה על אחיך: **בחרבי ובקשתי.** כשהרגו שמעון ולוי את אנשי שכם נתכנסו כל סביבותיהם להזדוג להם וחגר יעקב כלי מלחמה כנגדן. דבר אחר שכם אחד היא הבכורה שיטלו בניו שני חלקים, ושכם לשון חלק הוא, והרבה יש לו דומים במקרא (תהלים כא יג) כי תשיתמו שכם, תשית שונאי לפני לחלקים, (שם ס ח) אחלקה שכם, (הושע ו ט) דרך ירצחו שכמה, איש חלקו, (צפניה ג ט) לעבדו שכם אחד: **אשר לקחתי מיד האמרי.** מיד עשו שעשה מעשה אמורי. דבר אחר שהיה צד אביו באמרי פיו: **בחרבי ובקשתי.** היא חכמתו ותפלתו:
@27 **ואגידה לכם.** בקש לגלות את הקץ ונסתלקה שכינה ממנו והתחיל אומר דברים אחרים:
@29 **וראשית אוני.** היא טפה ראשונה שלו, שלא ראה קרי מימיו: **אוני.** כוחי, כמו (הושע יב ט) מצאתי און לי, (ישעיה מ כו) מרוב אונים, (שם כט) ולאין אונים: **יתר שאת.** ראוי היית להיות יתר על אחיך בכהנה, לשון נשיאות כפים: **ויתר עז.** במלכות, כמו (ש''א ב י) ויתן עז למלכו. ומי גרם לך להפסיד כל אלה:
@30 **פחז כמים.** הפחז והבהלה אשר מהרת להראות כעסך, כמים הללו הממהרים למרוצתם, לכך **אל תותר.** אל תרבה לטל כל היתרות הללו שהיו ראויות לך. ומהו הפחז אשר פחזת. **כי עלית משכבי אביך אז חללת.** אותו שעלה על יצועי, שם שכינה שהיה דרכה להיות עולה על יצועי: **פחז.** שם דבר הוא לפיכך טעמו למעלה וכלו נקוד פת''ח, ואלו היה לשון עבר היה נקוד חציו קמ''ץ וחציו פת''ח וטעמו למטה: **יצועי.** לשון משכב על שם שמציעים אותו על ידי לבדין וסדינין, והרבה דומים לו (תהלים קלב ג) אם אעלה על ערש יצועי, (תהלים סג ז) אם זכרתיך על יצועי:
@31 **שמעון ולוי אחים.** בעצה אחת על שכם ועל יוסף. (לעיל לז יט. כ) ויאמרו איש אל אחיו ועתה לכו ונהרגהו, מי הם, אם תאמר ראובן או יהודה, הרי לא הסכימו בהריגתו, אם תאמר בני השפחות, הרי לא היתה שנאתן שלמה, שנאמר (שם ב) והוא נער את בני בלהה ואת בני זלפה וגו' , יששכר וזבולן לא היו מדברים בפני אחיהם הגדולים מהם, על כרחך שמעון ולוי הם, שקראם אביהם אחים: **כלי חמס.** אמנות זו של רציחה, חמס הוא בידיהם, מברכת עשו היא, זו אמנות שלו היא, ואתם חמסתם אותה המנו: **מכרתיהם.** לשון כלי זין, הסיף בלשון יוני מכי''ר. דבר אחר מכרתיהם. בארץ מגורתם נהגו עצמן בכלי חמס, כמו (יחזקאל טז ג) מכרתיך ומלדתיך, וזה תרגום של אונקלוס:
@32 **בסדם אל תבא נפשי.** זה מעשה זמרי, כשנתקבצו שבטו של שמעון להביא את המדינית לפני משה, ואמרו לו זו אסורה או מתרת, אם תאמר אסורה, בת יתרו מי התירה לך, אל יזכר שמי בדבר, שנאמר (במדבר כה יד) זמרי בן סלוא נשיא בית אב לשמעוני, ולא כתב בן יעקב: **בקהלם.** כשיקהיל קרח שהוא משבטו של לוי את כל העדה על משה ועל אהרן: **אל תחד כבדי.** שם, אל יתיחד עמהם שמי, שנאמר (במדבר טז א) קרח בן יצהר בן קהת בן לוי, ולא נאמר בן יעקב אבל בדברי הימים כשנתיחסו בני קרח על הדוכן, נאמר (דה''א ו כב) בן קרח בן יצהר בן קהת בן לוי בן ישראל: **אל תחד כבדי.** כבוד לשון זכר הוא, ועל כרחך אתה צריך לפרש כמדבר אל הכבוד ואומר אתה כבודי אל תתיחד עמם, כמו (ישעיה יד כ) לא תחד אתם בקבורה: **כי באפם הרגו איש.** אלו חמור ואנשי שכם, ואינם חשובין כלם אלא כאיש אחד וכן הוא אומר בגדעון (שופטים ו טז) והכית את מדין כאיש אחד, וכן במצרים (שמות טו א) סוס ורוכבו רמה בים, זהו מדרשו. ופשוטו אנשים הרבה קורא איש, כל אחד לעצמו, באפם הרגו כל איש שכעסו עליו, וכן (יחזקאל יט ג) וילמד לטרף טרף אדם אכל: **וברצנם עקרו שור.** רצו לעקר את יוסף שנקרא שור, שנאמר (דברים לג יז) בכור שורו הדר לו. עקרו אישירוטו''ר בלע''ז [לכרות גידי השוק], לשון (יהושע יא ו) את סוסיהם תעקר:
@33 **ארור אפם כי עז.** אפלו בשעת תוכחה לא קלל אלא אפם, וזהו שאמר בלעם (במדבר כג ח) מה אקוב לא קבה אל: **אחלקם ביעקב.** אפרידם זה מזה שלא יהא לוי במנין השבטים, והרי הם חלוקים. דבר אחר אין לך עניים וסופרים ומלמדי תינוקות אלא משמעון, כדי שיהיו נפוצים, ושבטו של לוי עשאו מחזר על הגרנות לתרומות ולמעשרות, נתן לו תפוצתו דרך כבוד:
@34 **יהודה אתה יודוך אחיך.** לפי שהוכיח את הראשונים בקנטורים התחיל יהודה לסוג לאחוריו (שלא יוכיחנו על מעשה תמר) וקראו יעקב בדברי רצוי יהודה לא אתה כמותם: **ידך בערף איביך.** בימי דוד, שנאמר (ש''ב כב מא) ואויבי תתה לי ערף: **בני אביך.** על שם שהיו מנשים הרבה לא אמר בני אמך, כדרך שאמר יצחק (לעיל כז כט) :
@35 **גור אריה.** על דוד נתנבא, בתחלה גור (שמואל ב' ה ב) בהיות שאול מלך עלינו אתה היית המוציא והמביא את ישראל, ולבסוף אריה כשהמליכוהו עליהם, וזהו שתרגם אונקלוס שלטון יהא בשרויא, בתחלתו: **מטרף.** ממה שחשדתיך (לעיל לז לג) בטרף טרף יוסף חיה רעה אכלתהו, וזהו יהודה שנמשל לאריה: **בני עלית.** סלקת את עצמך, ואמרת (שם כו) מה בצע וגו' . וכן מהריגת תמר שהודה (לעיל לח כו) צדקה ממני, לפיכך כרע רבץ וגו' בימי שלמה (מ''א ה ה) איש תחת גפנו וגו' :
@36 **לא יסור שבט מיהודה.** מדוד ואלך, אלו ראשי גליות שבבבל שרודים את העם בשבט שממנים על פי המלכות: **ומחקק מבין רגליו.** תלמידים, אלו נשיאי ארץ ישראל: **עד כי יבא שילה.** מלך המשיח שהמלוכה שלו, וכן תרגם אנקלוס. ומדרש אגדה שילו, שי לו, שנאמר (תהלים עו יב) יובילו שי למורא: **ולו יקהת עמים.** אסיפת עמים, שהיו''ד עיקר היא ביסוד, כמו (יחזקאל כח יז) יפעתך, ופעמים שנופלת ממנו, וכמה אותיות משמשות בלשון זה והם נקראים עיקר נופל, כגון נו''ן של נוגף ושל נושך ואל''ף (איוב יג יז) שבאחותי באזניכם, (יחזקאל כא כ) ושבאבחת חרב (מ''ב ד ב) ואסוך שמן. אף זה יקהת עמים, אסיפת עמים, שנאמר (ישעיהו יא י) אליו גוים ידרשו, ודומה לו (משלי ל יז) עין תלעג לאב ותבז ליקהת אם, לקבוץ קמטים שבפנים מפני זקנתה. ובתלמוד (יבמות קו ב) דיתבי ומקהו אקהתא בשוקי דנהרדעא, ויכול היה לומר קהית עמים:
@37 **אסרי לגפן עירה.** נתנבא על ארץ יהודה שתהא מושכת יין כמעין, איש יהודה יאסר לגפן עיר אחד ויטעננו מגפן אחת, ומשורק אחד בן אתון אחד: **שרקה.** זמורה ארכה, קורייד''א בלע''ז [עריס]: **כבס ביין.** כל זה לשון רבוי יין: **סותה.** לשון מין בגד הוא, ואין לו דמיון במקרא: **אסרי.** כמו אוסר, דוגמתו (תהלים קיג ז) מקימי מעפר דל, (שם קכג א) היושבי בשמים, וכן בני אתנו כענין זה. ואונקלוס תרגם במלך המשיח. גפן הם ישראל, עירה זו ירושלים. שורקה אלו ישראל (ירמיה ב כא) ואנכי נטעתיך שורק: **בני אתונו.** יבנון היכליה, לשון שער האיתון בספר יחזקאל (מ טו) . ועוד תרגמו בפנים אחרים גפן אלו צדיקים. בני אתונו עבדי אוריתא באלפן, על שם (שופטים ה י) רוכבי אתונות צחורות. **כבס ביין.** יהא ארגוון טב לבושוהי, דומה ליין, וצבעונין הוא לשון סותה שהאשה לובשתן ומסיתה בהן את הזכר לתן עיניו בה. ואף רבותינו פרשו בתלמוד לשון הסתת שכרות במסכת כתבות (דף קיא ב) ועל היין, שמא תאמר אינו מרוה, תלמוד לומר סותה:
@38 **חכלילי.** לשון אודם כתרגומו וכן (משלי כג כט) למי חכלילות עינים, שכן דרך שותי יין עיניהם מאדימין: **מחלב.** מרוב חלב [שיהא בארצו מרעה טוב לעדרי צאן, וכן פרוש המקרא אדם עינים יהא מרוב יין, ולבן שנים יהא מרוב חלב]. ולפי תרגומו עינים לשון הרים, שמשם צופים למרחוק. ועוד תרגמו בפנים אחרות לשון מעינות וקלוח היקבים. נעווהי, יקבים שלו, ולשון ארמי הוא במסכת עבודה זרה (דף עד ב) נעוא ארתחו. יחורן בקעתיה, תרגם שנים לשון (ש''א יד ד) שני הסלעים:
@39 **זבלון לחוף ימים.** על חוף ימים תהיה ארצו. חוף כתרגומו ספר, מרק''א בלע''ז [גבול], והוא יהיה מצוי תדיר על חוף אניות, במקום הנמל, שאניות מביאות שם פרקמטיא, שהיה זבולן עוסק בפרקמטיא, וממציא מזון לשבט יששכר והם עוסקים בתורה, הוא שאמר משה (דברים לג יח) שמח זבולן בצאתך ויששכר באהליך, זבולן יוצא בפרקמטיא ויששכר עוסק בתורה באהלים: **וירכתו על צידן.** סוף גבולו יהיה סמוך לצידון. ירכתו, סופו, כמו (שמות כו כב) ולירכתי המשכן:
@40 **יששכר חמור גרם.** חמור בעל עצמות, סובל עול תורה כחמור חזק שמטעינין אותו משאוי כבד: **רבץ בין המשפתים.** כחמור המהלך ביום ובלילה ואין לו לינה בבית וכשהוא רוצה לנוח רובץ לו בין התחומין בתחומי העירות שמוליך שם פרקמטיא:
@41 **וירא מנוחה כי טוב.** ראה לחלקו ארץ מבורכת וטובה להוציא פירות: **ויט שכמו לסבל.** עול תורה: **ויהי.** לכל אחיו ישראל: **למס עבד.** לפסוק להם הוראות של תורה וסדרי עבורין, שנאמר (דה''א יב לג) ומבני יששכר יודעי בינה לעתים לדעת מה יעשה ישראל ראשיהם מאתים, מאתים ראשי סנהדראות העמיד, וכל אחיהם על פיהם: **ויט שכמו.** השפיל שכמו כמו (שמואל ב' כב י) ויט שמים (תהלים עח א) הטו אזנכם. ואונקלוס תרגמו בפנים אחרים ויט שכמו לסבל מלחמות ולכבוש מחוזות שהם יושבים על הספר, ויהי האויב כבוש תחתיו למס עובד:
@42 **דן ידין עמו.** ינקם נקמת עמו מפלשתים, כמו (דברים לב לו) כי ידין ה' עמו: **כאחד שבטי ישראל.** כל ישראל יהיו כאחד עמו ואת כלם ידין, ועל שמשון נבא נבואה זו. ועוד יש לפרש כאחד שבטי ישראל כמיוחד שבשבטים הוא דוד שבא מיהודה:
@43 **שפיפן.** הוא נחש. ואומר אני שקרוי כן על שם שהוא נושף, כמו (בראשית ג טו) ואתה תשופנו עקב: **הנשך עקבי סוס.** כך דרכו של נחש, ודמהו לנחש הנושך עקבי סוס, ונופל רכבו אחור שלא נגע בו. ודוגמתו מצינו בשמשון (שופטים טז כט) וילפת שמשון את שני עמודי התוך וגו' ושעל הגג מתו. ואונקלוס תרגם כחיוי חורמן, שם מין נחש, שאין רפואה לנשיכתו, והוא צפעוני, וקרוי חורמן על שם שעושה הכל חרם. וכפתנא, כמו פתן. יכמון, יארוב:
@44 **לישועתך קויתי ה'.** נתנבא שינקרו פלשתים את עיניו, וסופו לומר (שופטים טז כח) זכרני נא וחזקני נא אך הפעם וגו' :
@45 **גד גדוד יגודנו.** כלם לשון גדוד הם, וכך חברו מנחם. ואם תאמר אין גדוד בלא שני דלתי''ן, יש לומר גדוד שם דבר צריך שני דלתי''ן, שכן דרך תבה בת שתי אותיות לכפול בסופה, ואין יסודה אלא שתי אותיות, וכן אמר (משלי כו ב) כצפור לנוד, מגזרת (איוב ז ד) ושבעתי נדודים, (שופטים ה כז) שם נפל שדוד, מגזרת (תהלים צא ו) ישוד צהרים, אף יגוד, יגודנו, וגדוד, מגזרה אחת הם. וכשהוא מדבר בלשון יפעל אינו כפול, כמו יגוד, ינוד, ירום, ישוד, ישוב, וכשהוא מתפעל או מפעיל אחרים הוא כפול, כמו יתגודד, יתרומם, יתבולל, יתעודד. ובלשון מפעיל (תלים קמו ט) יתום ואלמנה יעודד, (ישע' מט ה) לשובב יעקב אליו, (שם נח יב) משובב נתיבות. יגודנו האמור כאן אינו לשון שיפעילוהו אחרים, אלא כמו יגוד המנו, כמו (ירמיה י כ) בני יצאוני, יצאו ממני. גד גדוד יגודנו. גדודים יגודו המנו, שיעברו הירדן עם אחיהם למלחמה כל חלוץ עד שנכבשה הארץ: **והוא יגוד עקב.** כל גדודיו ישובו על עקבם לנחלתם שלקחו בעבר הירדן, ולא יפקד מהם איש: **עקב.** בדרכן ובמסלותם שהלכו ישובו, כמו (תהלים עז כ) ועקבותיך לא נודעו, וכן (שה''ש א ח) בעקבי הצאן, בלשון לע''ז תרצי''ש [עקבות]:
@46 **מאשר שמנה לחמו.** מאכל הבא מחלקו של אשר יהא שמן, שיהיו זיתים מרבים בחלקו, והוא מושך שמן כמעין. וכן ברכו משה (דברים לג כד) וטבל בשמן רגלו, כמו ששנינו במנחות (דף פה ב) פעם אחת הצרכו אנשי לודקיא לשמן וכו' :
@47 **אילה שלחה.** זו בקעת גנוסר שהיא קלה לבשל פירותיה כאילה זו שהיא קלה לרוץ. אילה שלוחה. אילה משלחת לרוץ: **הנתן אמרי שפר.** כתרגומו. דבר אחר על מלחמת סיסרא נתנבא (שופטים ד ו) ולקחת עמך עשרת אלפים איש מבני נפתלי וגו' , והלכו שם בזריזות, וכן נאמר שם לשון שלוח (שופטים ה טו) בעמק שלח ברגליו: **הנתן אמרי שפר.** על ידם שרו דבורה וברק שירה. ורבותינו דרשוהו על יום קבורת יעקב כשערער עשו על המערה, במסכת סוטה (דף יג א) . ותרגומו יתרמי עדביה יפול חבלו, והוא יודה על חלקו אמרים נאים ושבח:
@48 **בן פרת.** בן חן, והוא לשון ארמי אפריון נמטייה לרבי שמעון בסוף בבא מציעא (קיט א) : **בן פרת עלי עין.** חנו נטוי על העין הרואה אותו: **בנות צעדה עלי שור.** בנות מצרים היו צועדות על החומה להסתכל ביפיו. ובנות הרבה צעדה, כל אחת ואחת במקום שתוכל לראותו משם. עלי שור. על ראיתו, כמו (במדבר כד יז) אשורנו ולא קרוב. ומדרשי אגדה יש רבים, וזה נוטה לישוב המקרא: **פרת.** תי''ו שבו הוא תקון הלשון, כמו (קהלת ג יח) על דברת בני האדם: **שור.** כמו לשור: **עלי שור.** בשביל לשור. ותרגום של אנקלוס בנות צעדה עלי שור תרין שבטין יפקון מבנוהי וכו' . וכתב בנות על שם בנות מנשה בנות צלפחד שנטלו חלק בשני עברי הירדן. ברי דיסגי יוסף פורת לשון פריה ורביה. ויש מדרשי אגדה המתישבים על הלשון בשעה שבא עשו לקראת יעקב, בכלן קדמו האמהות ללכת לפני בניהם להשתחוות, וברחל כתיב (לעיל לג ז) נגש יוסף ורחל וישתחוו. אמר יוסף רשע הזה עינו רמה, שמא יתן עיניו באמי, יצא לפניה ושרבב קומתו לכסותה, והוא שברכו אביו בן פורת, הגדלת עצמך יוסף עלי עין של עשו, לפיכך זכית לגדלה: **בנות צעדה עלי שור.** להסתכל בך בצאתך על מצרים. ועוד דרשוהו לענין שלא תשלט בזרעו עין רעה, ואף כשברך מנשה ואפרים ברכם כדגים שאין עין רעה שולטת בהם:
@49 **וימררהו ורבו.** וימררוהו אחיו, וימררוהו פוטיפר ואשתו לאסרו, לשון (שמות א יד) וימררו את חייהם: **ורבו.** נעשו לו אחיו אנשי ריב. ואין הלשון הזה לשון פעלו, שאם כן היה לו לנקד ורבו, כמו (במדבר כ יג) המה מי מריבה אשר רבו וגו' . ואף אם לשון רבית חצים הוא, כך היה לו להנקד. ואינו אלא לשון פעלו, כמו שמו שמים (ירמיה ב יב) , שהוא לשון הושמו, וכן (איוב כד כד) רומו מעט, שהוא לשון הורמו. אלא שלשון הורמו והושמו על ידי אחרים, ולשון שמו, רמו, רבו, מאליהם הוא, משוממים את עצמם, נתרוממו מעצמם, נעשו אנשי ריב. וכן (ישעיה כג ב) דמו יושבי אי, כמו נדמו. וכן תרגם אנקלוס ונקמוהי: **בעלי חצים.** שלשונם כחץ. ותרגומו לשון (במדבר לא לו) ותהי המחצה, אותן שהיו ראוים לחלוק עמו נחלה:
@50 **ותשב באיתן קשתו.** נתישבה בחזק. קשתו, חזקו: **ויפזו זרעי ידיו.** זו היא נתינת טבעת על ידו, לשון (מלכים א' י יח) זהב מופז, זאת היתה לו מידי הקדוש ברוך הוא שהוא אביר יעקב, ומשם עלה להיות רעה אבן ישראל, עיקרן של ישראל לשון (זכריה ד ז) האבן הראשה לשון מלכות. ואונקלוס אף הוא כך תרגמו. ותשב. ותבת בהון נביאותיה, החלומות אשר חלם להם, על דקים אוריתא בסתרא, תוספת הוא ולא מלשון עברי שבמקרא, ושוי תוקפא רוחצניה, תרגום של באיתן קשתו, וכך לשון התרגום על העברי ותשב נבואתו, בשביל שאיתנו של הקדוש ברוך הוא היתה לו לקשת ולמבטח. בכן יתרמא דהב על דרעוהי, לכך ויפזו זרעי ידיו, לשון פז: **אבן ישראל.** לשון נוטריקון אב ובן, אבהן ובנין, יעקב ובניו. ורבותינו דרשו ותשב באיתן קשתו על כבישת יצרו באשת אדוניו, וקוראו קשת על שם שהזרע יורה כחץ. ויפזו זרעי ידיו, כמו ויפוצו. שיצא הזרע מבין אצבעות ידיו: **מידי אביר יעקב.** שנראתה לו דמות דיוקנו של אביו וכו' כדאיתא בסוטה (דף לו ב) :
@51 **מאל אביך.** היתה לך זאת והוא יעזרך: **ואת שדי.** ועם הקדוש ברוך הוא היה לבך, כשלא שמעת לדברי אדונתך והוא יברכך: **ברכת שדים ורחם.** ברכתא דאבא ודאמא, כלומר יתברכו המולידים והיולדות, שיהיו הזכרים מזריעין טפה הראויה להריון, והנקבות לא ישכלו את רחם שלהן להפיל עבריהן: **שדים.** כמו (שמות יט יג) ירה יירה, דמתרגמינן אישתדאה ישתדי, אף שדים כאן על שם שהזרע יורה כחץ:
@52 **ברכת אביך גברו** וגו' **.** הברכות שברכני הקדוש ברוך הוא גברו והלכו על הברכות שברך את הורי: **עד תאות גבעות עולם.** לפי שהברכות שלי גברו עד סוף גבולי גבעות עולם, שנתן לי ברכה פרוצה בלי מצרים, מגעת עד ארבע קצות העולם שנאמר (לעיל כח יד) ופרצת ימה וקדמה וגו' , מה שלא אמר לאברהם אבינו וליצחק. לאברהם אמר (שם יג יד. טו) שא נא עיניך וראה צפנה וגו' , כי את כל הארץ אשר אתה רואה לך אתננה, ולא הראהו אלא ארץ ישראל בלבד, ליצחק אמר (שם כו ג) כי לך ולזרעך אתן את כל הארצות האל והקימותי את השבועה וגו' , זהו שאמר ישעיה (נח יד) והאכלתיך נחלת יעקב אביך, ולא אמר נחלת אברהם: **תאות.** אשמול''ץ בלע''ז [גבול], כך חברו מנחם בן סרוק: **הורי.** לשון הריון, שהורוני במעי אמי, כמו (איוב ג ג) הורה גבר: **עד תאות.** עד קצות, כמו (במדבר לד י) והתאויתם לכם לגבול קדמה (שם לד ח) תתאו לבא חמת: **תהיין.** כלם לראש יוסף: **נזיר אחיו.** פרישא דאחוהי, שנבדל מאחיו, כמו (ויקרא כב ב) וינזרו מקדשי בני ישראל, (ישעיה א ד) נזרו אחור. ואונקלוס תרגם תאות גבעת עולם, לשון תאוה וחמדה, וגבעות לשון (שמואל א' ב ח) מצוקי ארץ, שחמדתן אמו והזקיקתו לקבלם:
@53 **בנימין זאב יטרף.** זאב הוא אשר יטרף, נבא על שיהיו עתידין להיות חטפנין (שופטים כא כא) וחטפתם לכם איש אשתו, בפילגש בגבעה, ונבא על שאול שיהיה נוצח באויביו סביב, שנאמר (ש''א יד מז) ושאול לכד המלוכה וילחם וגו' במואב ובאדום ובכל אשר יפנה ירשיע: **בבקר יאכל עד.** לשון בזה ושלל, המתורגם (במדבר לא יב) עדאה. ועוד יש לו דומה בלשון עברית (ישעיה לג כג) אז חלק עד שלל מרבה, ועל שאול הוא אומר שעמד בתחלת פריחתן וזריחתן של ישראל: **ולערב יחלק שלל.** אף משתשקע שמשן של ישראל על ידי נבוכדנצר שיגלם לבבל, יחלק שלל. מרדכי ואסתר שהם מבנימין יחלקו את שלל המן, שנאמר (אסתר ח ז) הנה בית המן נתתי לאסתר. ואונקלוס תרגם על שלל הכהנים בקדשי המקדש:
@54 **וזאת אשר דבר להם אביהם ויברך אותם.** והלא יש מהם שלא ברכם אלא קנטרן. אלא כך פרושו וזאת אשר דבר להם אביהם מה שנאמר בענין. יכול שלא ברך לראובן שמעון ולוי, תלמוד לומר ויברך אותם, כלם במשמע: **איש אשר כברכתו.** ברכה העתידה לבא על כל אחד ואחד: **ברך אתם.** לא היה לו לומר אלא איש אשר כברכתו ברך אותו, מה תלמוד לומר ברך אותם, לפי שנתן ליהודה גבורתו של אריה, ולבנימין חטיפתו של זאב, ולנפתלי קלותו של איל, יכול שלא כללן בכל הברכות, תלמוד לומר ברך אותם:
@55 **נאסף אל עמי.** על שם שמכניסין הנפשות אל מקום גניזתן, שיש אסיפה בלשון עברי שהיא לשון הכנסה, כגון (שופטים יט טו) ואין איש מאסף אותם הביתה, (דברים כב ב) ואספתו אל תוך ביתך, (ויק' כג לט) באספכם את תבואת הארץ, הכנסתם לבית מפני הגשמים, (שמות כג טז) באספך את מעשיך. וכל אסיפה האמורה במיתה אף היא לשון הכנסה: **אל אבותי.** עם אבותי:
@59 **ויאסף רגליו.** הכניס רגליו: **ויגוע ויאסף.** ומיתה לא נאמרה בו, ואמרו רבותינו זכרונם לברכה יעקב אבינו לא מת:
@61 **לחנט את אביו.** ענין מרקחת בשמים הוא:
@62 **וימלאו לו.** השלימו לו ימי חניטתו עד שמלאו לו ארבעים יום: **ויבכו אתו מצרים שבעים יום.** ארבעים לחניטה, ושלשים לבכיה, לפי שבאה להם ברכה לרגלו, שכלה הרעב, והיו מי נילוס מתברכין:
@64 **אשר כריתי לי.** כפשוטו כמו (שמות כא לג) כי יכרה איש. ומדרשו עוד מתישב על הלשון, כמו אשר קניתי. אמר רבי עקיבא כשהלכתי לכרכי הים היו קורין למכירה כירה, ועוד מדרשו לשון כרי, דגור, שנטל יעקב כל כסף וזהב שהביא מבית לבן ועשה אותו כרי, ואמר לעשו טול זה בשביל חלקך במערה:
@65 **כאשר השביעך.** ואם לא בשביל השבועה לא הייתי מניחך, אבל ירא לומר עבור על השבועה, שלא יאמר אם כן אעבר על השבועה שנשבעתי לך שלא אגלה על לשון הקדש שאני מכיר עודף על שבעים לשון ואתה אינך מכיר בו, כדאיתא במסכת סוטה (דף לו ב) :
@69 **גרן האטד.** מקף אטדין היה. ורבותינו דרשו על שם המאורע שבאו כל מלכי כנען ונשיאי ישמעאל למלחמה, וכיון שראו כתרו של יוסף תלוי בארונו של יעקב, עמדו כלן ותלו בו כתריהם, והקיפוהו כתרים כגרן המקף סיג של קוצים:
@71 **כאשר צום.** מהו אשר צום:
@72 **וישאו אתו בניו.** ולא בני בניו, שכך צום אל ישאו מטתי, לא איש מצרי, ולא אחד מבניכם שהם מבנות כנען, אלא אתם, וקבע להם מקום, שלשה למזרח וכן לארבע רוחות, וכסדרן למסע מחנה של דגלים נקבעו כאן. לוי לא ישא שהוא עתיד לשאת את הארון, ויוסף לא ישא שהוא מלך, מנשה ואפרים יהיו תחתיהם, וזהו (במדבר ב ב) איש על דגלו באתת, באות שמסר להם אביהם לשא מטתו:
@73 **הוא ואחיו וכל העלים אתו.** בחזרתן כאן הקדים אחיו למצרים העולים אתו, ובהליכתן הקדים מצרים לאחיו, שנאמר (לעיל פסוק ז) ויעלו אתו כל עבדי פרעה וגו' ואחר כך (שם ח) כל בית יוסף ואחיו, אלא לפי שראו הכבוד שעשו מלכי כנען שתלו כתריהם בארונו של יעקב נהגו בהם כבוד:
@74 **ויראו אחי יוסף כי מת אביהם.** מהו ויראו, הכירו במיתתו אצל יוסף, שהיו רגילים לסעוד עמו על שלחנו של יוסף והיה מקרבן בשביל כבוד אביו, ומשמת יעקב לא קרבן: **לו ישטמנו.** שמא ישטמנו. לו מתחלק לענינים הרבה, יש לו משמש בלשון בקשה ולשון הלואי, כגון (לעיל ל לד) לו יהי כדברך, (שם כג יג) לו שמעני, (יהושע ז ז) ולו הואלנו, (במדבר יד ב) לו מתנו. ויש לו משמש בלשון אם ואולי, כגון (דברים לב כט) לו חכמו, (ישעיה מח יח) לוא הקשבת למצותי, (שמואל ב' יח יב) ולו אנכי שקל על כפי. ויש לו משמש בלשון שמא לו ישטמנו, ואין לו עוד דומה במקרא, והוא לשון אולי, כמו (לעיל כד לט) אולי לא תלך האשה אחרי לשון שמא הוא, ויש אולי לשון בקשה כגון (שמו''ב טז יב) אולי יראה ה' בעיני, (יהושע יד יב) אולי ישיב ה' אותי, הרי הוא כמו, (לעיל ל לד) לו יהי כדברך, ויש אולי לשון אם, (לעיל יח כד) אולי יש חמשים צדיקם:
@75 **ויצוו אל יוסף.** כמו (שמות ו יג) ויצום אל בני ישראל, צוה למשה ולאהרן להיות שלוחים אל בני ישראל, אף זה ויצוו אל שלוחם להיות שליח אל יוסף לומר לו כן. ואת מי צוו, את בני בלהה שהיו רגילין אצלו, שנאמר (לעיל לז ב) והוא נער את בני בלהה: **אביך צוה.** שנו בדבר מפני השלום, כי לא צוה יעקב כן שלא נחשד יוסף בעיניו:
@76 **שא נא לפשע עבדי אלהי אביך.** אם אביך מת אלהיו קים, והם עבדיו:
@77 **וילכו גם אחיו.** מוסף על השליחות:
@78 **כי התחת אלהים אני.** שמא במקומו אני, בתמיהה, אם הייתי רוצה להרע לכם, כלום אני יכול, והלא אתם כלכם חשבתם עלי רעה והקדוש ברוך הוא חשבה לטובה, והיאך אני לבדי יכול להרע לכם:
@80 **וידבר על לבם.** דברים המתקבלים על הלב, עד שלא ירדתם לכאן היו מרננים עלי שאני עבד, ועל ידיכם נודע שאני בן חורין, ואם אני הורג אתכם מה הבריות אומרות כת של בחורים ראה ונשתבח בהן, ואמר אחי הם, ולבסוף הרג אותם, יש לך אח שהורג את אחיו. דבר אחר עשרה נרות לא יכלו לכבות נר אחד וכו' :
@82 **על ברכי יוסף.** כתרגומו, גדלן בין ברכיו:

@1 **ויחי יעקב בארץ מצרים שבע עשרה שנה** . כבר הזכרתי (לעיל מג יד) כי רדת יעקב למצרים הוא גלותינו היום ביד החיה הרביעית (דניאל ז ז) רומי הרשעה כי בני יעקב הם עצמם סבבו רדתם שם במכירת יוסף אחיהם ויעקב ירד שם מפני הרעב וחשב להנצל עם בנו בבית אוהב לו כי פרעה אוהב את יוסף וכבן לו והיו סבורים לעלות משם ככלות הרעב מארץ כנען כמו שאמרו (לעיל מז ד) לגור בארץ באנו כי אין מרעה לצאן אשר לעבדיך כי כבד הרעב בארץ כנען והנה לא עלו אבל ארך עליהם הגלות ומת שם ועלו עצמותיו וזקני פרעה ושריו העלוהו ועשו עמו אבל כבד וכן אנחנו עם רומי ואדום אחינו הסיבונו ביאתינו בידם כי כרתו ברית עם הרומיים ואגריפס המלך האחרון לבית שני ברח אליהם לעזרה ומפני הרעב נלכדו אנשי ירושלים והגלות ארך עלינו מאד לא נודע קצו כשאר הגליות ואנחנו בו כמתים אומרים יבשו עצמותינו נגזרנו לנו ויעלו אותנו מכל העמים מנחה לה' ויהיה להם אבל כבד בראותם כבודנו ואנחנו נראה בנקמת ה' יקימנו ונחיה לפניו
@2 **ויקרבו ימי ישראל למות** . פתרונו כאשר קרבו ימי ישראל למות קרא לבנו ליוסף והוא בשנה האחרונה לימיו וענינו כי הרגיש בעצמו אפיסת הכחות ויתרון החולשה ואיננו חולה אבל ידע כי לא יאריך ימים ולכן קרא לבנו ליוסף ואחרי שוב יוסף למצרים חלה והוגד ליוסף ובא לפניו עם שני בניו כדי שיברכם וכן ויקרבו ימי דוד למות (מלכים א ב א) ושם (שם פסוק ב) נאמר אנכי הולך בדרך כל הארץ כי ידע בנפשו כן
@4 **השבעה לי וישבע לו** . לא היה יעקב חושד בבנו הצדיק האהוב לו שימרה על מצות אביו ועל הדבר אשר הבטיחו ואמר אנכי אעשה כדבריך אבל עשה כן לחזק הענין בעיני פרעה אולי לא יתן לו רשות להפרד ממנו ויאמר לו שלח את אחיך ואת עבדיך ויעלוהו שם או שיחפוץ פרעה שיקבר הנביא בארצו לכבוד להם ולזכות ולכן השביעו כי לא יהיה נכון להעבירו על שבועתו וגם יוסף יצטרך יותר להשתדל בענין מפני השבועה וכן היה הדבר כמו שאמר (להלן נ ו) עלה וקבור את אביך כאשר השביעך
@10 **ומולדתך אשר הולדת אחריהם** . אם תוליד עוד בנים לא יהיו במנין בני אלא בתוך שבטי אפרים ומנשה יהיו נכללין ולא יהא להם שם כשאר השבטים לענין הנחלה ואף על פי שנתחלקה ארץ ישראל למנין גולגלותם כדכתיב לרב תרבה נחלתו וכל איש נטל בשוה חוץ מן הבכורות מכל מקום לא נקראו שבטים אלא אלו לשון רש"י וזה איננו נכון שאם כן אין הבכורה ליוסף אלא לענין הכבוד בלבד שיקראו בניו שבטים והכתוב אומר בנחלתם ובגמרא אמרו לנחלה הקשתים לראובן ושמעון ולא לדבר אחר וכו' כדאיתא בהוריות (ו) והזכירו רבותינו בכל מקום (ב"ב קכג) שהיה יוסף בכור לנחלה וירש פי שנים כאחד כמשפט כל בכור ולא היתה בכורתו להקרא שבטים בלבד כדברי הרב ומזה נלמוד עוד שלא חלקו הארץ לכל שבטי ישראל לגולגלותם שאם כן מה הבכורה הזאת בירושה ואם נאמר שנתנו לכל אחד ואחד מבני יוסף פי שנים כאחד מכל אישי שאר השבטים לא הוזכר זה בכתוב כלל ולא מצינו ביעקב שיתן בכורה ליוסף אלא שאמר בכאן כראובן ושמעון יהיו לי ומזה אמר הכתוב (דהי"א ה א) נתנה בכורתו לבני יוסף בן ישראל אם כן היו לגמרי כשני שבטים והיא בכורתו וכך הם דברי חכמים בכל מקום (ב"ב קכג) אבל הענין איננו כלל כמו שאמר הרב שארץ ישראל לשבטים נתחלקה שנים עשר חלקים שוים עשו ממנה ונטל שבט שמעון הממועט שבהם כשבט יהודה שמרובה באוכלוסין ונטלו אפרים ומנשה כראובן ושמעון בשוה וכך העלו בגמרא פרק יש נוחלין (שם) וכתוב (יחזקאל מז יג) תתנחלו בארץ לשנים עשר שבטי ישראל יוסף חבלים וכן אמר אונקלוס (להלן מט כב) תרין שבטין יפקון מבנוהי יקבלון חולקא ואחסנתא שיהיו שוים בקבלת הנחלה וטעם חולקא חלק בכור ואחסנתא ירושת הפשוט ומה מה שאמר הכתוב (במדבר כו נד) לרב תרבה נחלתו ולמעט תמעיט לענין בתי אבות הנזכרים בפרשה דבר הכתוב שהשבט מחלק חלקו לבתי אבות של יוצאי מצרים ובית אב מרובה נותנין לו חלק גדול ובית אב ממועט נותנין לו חלק קטן ומתים יורשים החיים כמפורש בספרי (פנחס קלב) ורש"י הזכירו בפרשת פנחס (במדבר כו נה) והכלל בענין יוסף שהיה בכור לנחלה ואם חלקו ישראל הארץ לשבטים כמוזכר בגמרא (ב"ב קכא) נתנו לו כראובן ושמעון בשוה ואם אולי נאמר שחלקוהו לגולגלותם כנגלה מן הכתוב נתנו להם כפלים במספרם חלק פשוט כדין שאר האנשים וחלק שני בכורה ויהיה טעם כראובן ושמעון כפלים במספרם אבל שיהיה יוסף כשאר השבטים בנחלה ותהיה הבכורה להקרא שני שבטים כמאמר הרב זה דבר שאי אפשר בשום פנים
@11 **ואקברה שם** . כתוב בפירוש רש"י ולא הולכתיה אפילו לבית לחם להכניסה לארץ ולא ידעתי מהו וכי בחוצה לארץ נקברה חס ושלום שהרי בארץ מתה ושם נקברה כמו שנאמר כאן בפרשה מתה עלי רחל בארץ כנען ושם כתוב עוד מפורש (לעיל לה ו) ויבא יעקב לוזה אשר בארץ כנען היא בית אל וכתיב (שם פסוק טז) ויסעו מבית אל ויהי עוד כברת הארץ לבא אפרתה ומתה בדרך בין בית אל ובין בית לחם אפרתה בארץ ישראל
@11 "ואקברה שם" - וידעתי שיש בלבבך עלי אבל דע לך שעל פי הדיבור קברתיה שם שתהא לעזרה לבניה כשיגלם נובזראדן והיו עוברים דרך שם יצתה על קברה ובקשה רחמים עליהם שנאמר (ירמיהו לא יד) קול ברמה נשמע רחל מבכה על בניה והקב"ה משיבה יש שכר לפעולתך וגו' ושבו בנים לגבולם לשון רש"י וצריך על כל פנים שיהיה רמז במקרא לטעם הזה שאמר באגדה זו ושמא זהו מה שאמר הכתוב
@11 "מתה עלי רחל בדרך ואקברה שם בדרך" - כלומר בדרך אשר יעברו בה בניה מתה ושם קברתיה לטובתם כי היא לא מתה בדרך רק ברמה שהיא עיר בארץ בנימין ושם נקברה אבל בדרך של עתיד מתה והכתוב לא יפרש בעתידות רק ירמוז בהם ועל דרך הפשט גם כן אמר לו כן כמתנצל שלא יחר ליוסף בראות חפצו בקבורת המערה על שלא קבר אמו שם וכאשר קבר שם את לאה ולכך אמר לו כי מתה בארץ כנען ולא נקברה בחוצה לארץ כאשר תהיה קבורת מצרים ליעקב ומתה בדרך בפתע פתאום ולא יכול לקברה שם כי איך יעזוב את בניו ואת מקנהו בדרך וילך מהרה עמה למערת המכפלה ואיה הרופאים והרפואות לחנט אותה וזה טעם "עלי" ואף על פי שמערת המכפלה אינה רחוקה משם רק כחצי יום היה יעקב כבד מאד במקנה הגדול ובני בית ולא יגיעו שם רק בימים רבים וכן עשה בדרך ההוא ימים רבים עד בואו אל אביו ושנו חכמים (מו"ק כז) ולא של נשים לעולם מפני הכבוד ואני סבור שהיו אלו דברי התנצלות וגם יוסף יודע שמתה בדרך ונקברה בארץ וכבוד עשה לה במותה אבל הכוונה ליעקב שלא הוליך אותה למערה כדי שלא יקבור שם שתי אחיות כי יבוש מאבותיו ולאה היא הנשאת לו ראשונה בהיתר ורחל באהבתו אותה בנדר אשר נדר לה לקחה
@13 **אשר נתן לי אלהים בזה** . לא היה יוסף צריך להודיע לאביו כי במצרים נולדו לו שהרי כשפירש ממנו לא היה לו אשה ובנים והוא אמר לו כבר שני בניך הנולדים לך בארץ מצרים ונראה לי כי פירוש "בזה" בענין הזה שאמרת שנתנם לי השם קודם בואך אלי מצרימה והם אשר אמרת עליהם שהם לך וכן ובזה הנערה באה אל המלך (אסתר ב יג) ואמר נתן לי אלהים שעשה לי השם נסים עד שנתן לי המלך האשה והיו לי הבנים האלה ממנה
@19 **ויברך את יוסף ויאמר** . הטעם כי לברך את יוסף באהבתו אותו ברך את בניו ויגיד כי לא היה ליוסף זרע אחר והיתה כל ברכתו בברכת אלה הנערים או שיקראו שאר בניו על שם אחיהם ומברכתם יבורכו גם הם והוא הנכון בעיני כי הנביא אומר ומולדתך אשר הולדת אחריהם לך יהיו ודברו לא יהיה לריק אבל הוליד אחרי כן בנים כדעת אונקלוס שאמר ובנין דתוליד בתריהון ויהיה אשר הולדת עבר במקום עתיד כמו אשר לקחתי מיד האמורי ורבים מלבדו כי על דרך הפשט יראה שכבר היו לו בנים שהוליד אחרי בואו אליו מצרימה ממה שהוצרך להאריך ולא אמר "ועתה שני בניך הנולדים לך אפרים ומנשה כראובן ושמעון יהיו לי ומולדתך אשר תוליד לך יהיו" וזה טעם מה שאמר (לעיל מא נ) וליוסף יולד שני בנים בטרם תבא שנת הרעב כי אחרי הרעב נולדו לו עוד בנים אחרים והכתוב לא יזכיר אותם כי אין בהם צורך
@19 "האלהים אשר התהלכו אבותי לפניו אברהם ויצחק" - יקרא הנביא אל אלהי אבותיו אשר לו הגדולה והגבורה ועשה עמהם את הגדולות ואת הנוראות ויקרא לאלהי האמת אשר הוא רועה אותו מעודו ויתכן שיהיה הרועה אותי מגזרת רעך ורע אביך אל תעזוב (משלי כז י) כי במדה ההיא שלום ורעות והמלאך הגואל הוא העונה אותו בעת צרתו ושאמר לו אנכי האל בית אל (לעיל לא יג) והוא שנאמר עליו (שמות כג כא) כי שמי בקרבו ולכך אמר בקרב הארץ והרי זה מבואר למשכיל ואל יקשה עליו מעודי עד היום הזה עם מה שכתבנו בפסוק ויזבח זבחים לאלהי אביו יצחק (לעיל מו א) כי מעודו ינחהו בדרך אמת אבל לא נתיחד לו המדה עד שובו לארץ אבותיו מפני היותו בחוצה לארץ גם בעבור שהוצרך להתנהג עם לבן בדרך פתלתול ואיננו דרך האמת
@20 **וטעם ויקרא בהם שמי** . אמר רבי אברהם שנקראו ישראל על שם אפרים כאשר הם נקראים זרע אברהם יצחק ויעקב ואיננו נכון כי הכתוב אמר "בהם" והנה לא נקראו על שם מנשה ואולי בעבור שיקראו בית יוסף והנכון שיעמוד זרעם ושמם ויהיה שם אברהם יצחק ויעקב נזכר בהם לעולם
@21 **וירע בעיניו** . אולי יוסף היה אוהב את מנשה יותר בעבור היותו בכור לכן חרה לו והנכון בעיני כי חשב שטעה אביו בהם ואם היתה ברכתו בבלי דעת לא תבא ברכתו עליהם כי איננה ברוח הקדש כראוי וכאשר אמר לו ידעתי בני ידעתי נתפייס
@24 **ויברכם ביום ההוא** . טעם ביום ההוא בעבור שיוסף יפצר בו לשום מנשה ראשון הגיד כי לא רצה להסיר יד ימינו מראש אפרים על ראש מנשה ולא עוד אלא שחזר ואמר בפירוש במעמד ההוא בפני יוסף בברכו אותם "כאפרים וכמנשה"
@24 "וישם את אפרים לפני מנשה" - בכל ברכותיו וטעם בך יברך ישראל אל יוסף ידבר כי בזרעך יברך עם ישראל ויאמר למתברך ישימך אלהים כאפרים וכמנשה
@26 **ואני נתתי לך שכם אחד על אחיך** . אחרי שבירך את בני יוסף ועשאם שני שבטים חזר על יוסף ואמר לו הנה אנכי מת והיה אלהים עמכם בגלות להציל אתכם מכל צרה ותפרו ותרבו מאד וישיב אתכם אל ארץ אבותיכם לנחול אותה ואני כבר נתתי לך בארץ ההיא החלק האחד אשר בידי לתת והוא חלק הבכורה להיותך בו יתר על אחיך מיום שלקחתי אותו מיד האמורי בחרבי ובקשתי וזה כלו פיוס ליוסף ואהבתו אותו כי הודיעו שנתן לו הבכורה להיות בניו מעתה מתברכים להעשות שני שבטים גם בדגלי המדבר וחנוכת הנשיאים וגם החלק אשר לו בנחלה נתן לו שיזכה בו כאשר יכבשו הארץ בחרב ובקשת ובמלחמה והנה אמר לו עשיתי עמך כל הטובה שיכלתי לעשות לך לעת שהייתי יכול לעשותה כי אין ברשות יעקב בארץ רק שכם אחד שאין בידו לגזול מאחד מבניו את נחלתו רק הבכורה היתה לו לתת אותה לטוב בעיניו והנה נתן אותה אליו וטעם מיד האמורי כי ישראל לקחו הארץ תחילה מיד האמורי כי סיחון ועוג שני מלכי האמורי היו והמלחמה הראשונה והגדולה שהיתה להם בכבוש הארץ היתה לבניו של יוסף עם האמורי היא מלחמת יהושע עמם ובם נעשה הנס הגדול כדכתיב (יהושע י יב) אז ידבר יהושע לה' ביום תת ה' את האמורי לפני בני ישראל וגו' ומיד האמורי היה חלק ונחלה לבני יוסף כמו שכתוב (במדבר לב לט) וילכו בני מכיר בן מנשה גלעדה וילכדוה ויורש את האמורי אשר בה וגם בני אפרים נחלו בגבול האמורי כמו שכתוב (שופטים א לה) ויואל האמורי לשבת בהר חרס באילון ובשעלבים ותכבד יד בית יוסף ויהיו למס וטעם בחרבי ובקשתי כי הארץ לא תכבש להם רק בחרב ובקשת ירמוז למה שאמר הכתוב (יהושע יא יט כ) לא היתה עיר אשר השלימה אל בני ישראל בלתי החוי יושבי גבעון את הכל לקחו במלחמה כי מאת ה' היתה לחזק לבם לקראת המלחמה את ישראל למען החרימם וייחס החרב והקשת אליו כי זכותו היא העושה עמם מלחמה והיא הנלחם להם לא הם עצמם וכענין שאמר הכתוב (תהלים מד ד) כי לא בחרבם ירשו ארץ וזרועם לא הושיעה למו כי ימינך וזרועך ואור פניך כי רציתם וזהו בזכות האבות כי על דרך האמת ימינך לאברהם וזרועך ליצחק ואור פניך ליעקב וקרוב אלי עוד שעשה יעקב כדרך שיעשו הנביאים נטה ידו בחרב כנגד ארץ האמורי וזרק שם חצים להיותה נכבשת לבניו כענין שעשה אלישע וישם ידיו על ידי המלך ויאמר אלישע ירה ויור (מלכים ב יג טז) ואף על פי שלא סיפר הכתוב כן ירמזנו בפסוק הזה ויתכן שזה טעם אמרו לקחתי כי מאז לוקחה הארץ לבניו
@27 **באחרית הימים** . הם ימות המשיח כי יעקב ירמוז אליו בדבריו כמו שאמר עד כי יבא שילה ולו יקהת עמים ורבותינו אמרו (פסחים נו) שבקש לגלות את הקץ ונסתלקה ממנו שכינה כי לדברי הכל אחרית הימים ימות המשיח הם
@29 **ראובן בכורי אתה** . שיעור הפסוק הזה ראובן אתה בכורי וכחי וראשית אוני יתר שאתי ויתר עוזי וענינו אתה בכור כחי וראשית אוני בהיותי ביתרון שאת ומעלה כלשון הלא שאתו תבעת אתכם (איוב יג יא) משאתו יגורו אלים (שם מא יז) רוממות וגדולה ובהיותי יתרון עז למלחמה כמו ויתן עז למלכו (שמואל א ב י) ועזוז מלחמה (ישעיהו מב כה)
@30 **פחז כמים אל תותר** . פחז שם דבר מן אנשים רקים ופוחזים (שופטים ט ד) ריקים ונמהרים קלי הדעת ורבותינו משתמשים בו תדיר (נדרים ט) נסתכלתי בבבואה שלי ופחז יצרי עלי כלומר קפץ יצרי עלי ואמרו עוד (סנהדרין נז) אפיחזיהו הוא דקא מגלי כלומר קלות דעתם עמא פחיזא דאקדמיה פומיה לאודניה עדין בפחזותיכו קימיתו (שבת פח) נמהרים קלי דעת ויתכן שהוא הפוך מן חפזון יאמר שטף הבא כמים אל תותר בו כי עלית משכבי אביך בפחזותיך וקלות דעתך אז חללת אותם כאשר יצועי עלה הפחז שלך שהוא כמים העולים ושוטפים וזה כלשון הכתוב במים הנה ה' מעלה עליהם את מי הנהר העצומים והרבים ועלה על כל אפיקיו והלך על כל גדותיו וחלף ביהודה ושטף ועבר (ישעיה ח ז ח) ורבותינו אמרו (עיין שבת נה) אז חללת יצועי עלה שכינה שדרכה לעלות על יצועי והכתוב אומר (דהי"א ה א) ובחללו יצועי אביו שהיצוע הוא המחולל ואולי יכנה אותו שם ואם בדרך כנוי יתכן שיהיה העולה יעקב עצמו כלשון אם אעלה על ערש יצועי (תהלים קלב ג) ויאמר אז חללת אותי רק דבר בנסתר דרך כבוד וכן ובחללו יצועי אביו כנוי בחללו העולה על יצועי אביו ומן הכתוב הזה כפי פשוטו נראה כמו שפירשתי בסדר וישלח (לעיל לה כב) כי ראובן נתכוון לפסול את בלהה מאביו כדי שלא תלד לו עוד בנים וימעיטו בכורתו על כן אמר לו שהוא פחיזות וקלות דעת שיחשוב להרויח ולא יבא לו ממנו יתרון רק הפסד
@31 (בראשית מט ה): "שמעון ולוי אחים" - יאמר בעלי אחוה, כי יחם לבם על אחותם. ילמד עליהם זכות, כי בקנאתם על האחוה עשו מה שעשו, לומר שאין ראוים לעונש גדול, ולא החטא ראוי לימחל, כי הוא "חמס".
@31 והנכון בעיני, שאמר כי "שמעון ולוי אחים" גמורים, דומים ומתאחים זה לזה בעצתם ומעשיהם.
@31 וכבר פירשתי (בראשית לד יג), כי יעקב קצף על שמעון ולוי בהרגם אנשי העיר בעבור שעשו חמס, כי הם לא חטאו להם כלל ובאו בברית ונמולו, ואולי ישובו אל ה' ויהיו כולם בכלל אנשי בית אברהם, ומן הנפש אשר עשו בחרן. ועוד חרה לו, שלא יאמרו כי בעצתו נעשה הדבר, ויהיה חילול השם שיעשה הנביא חמס ושוד. וזה טעם (בראשית מט ו): "בסודם אל תבא נפשי" - התנצלות שלא היה בסודם בענותם במרמה, ובקהלם לא נתיחד כשבאו על העיר והרגום. ולכן יקלל (בראשית מט ז): "אפם ועברתם". וכן תרגם אונקלוס: "ברזיהון לא הות נפשי באיתכנשיהון למהך וכו'".
@31 ופירוש "כלי חמס מכרותיהם" - על דעת אונקלוס וכל המפרשים (ראב"ע, רש"י, רד"ק) כלי חמס מגורותיהם, וכן (יחזקאל טז ג): "מכורותיך ומולדתיך", וכן (יחזקאל כט יד): "על ארץ מכורתם", אמרו כי פירושו שעשו חמס בארץ מגורותיהם. ואם כן, יהיה שיעור הכתוב: כלי חמס להם במגורותיהם. ויקרא אותה "ארץ מגורותיהם", שגרו בה אחרי כן.
@31 אבל לפי דעתי יאמר "כלי חמס" הם מגורותיהם, חייהם, כלשון (בראשית מז ט): "ימי מגורי"; יאמר, כי כלי החמס עצמם הם מגוריהם, כי בם יחיו ויזונו. ודומה לזה (איוב כד ה): "ערבה לו לחם לנערים".
@31 ובעבור זה (בראשית מט ז): "יחלקם ביעקב", שלא יוסדו; "ויפיצם בישראל", שלא יקהלו, ויהי להם כן, כי נחלת שמעון בתוך בני יהודה, כדכתיב (יהושע יט א): "ויהי נחלתם בתוך נחלת בני יהודה", והיו עריהם מחולקות זו מזו בכל שבט יהודה, ונחלת לוי, ערי מקלט, מנופצות בכל ישראל.
@32 כבר פירשתי (בראשית לד יג), כי יעקב קצף על שמעון ולוי בהרגם אנשי העיר בעבור שעשו חמס, כי הם לא חטאו להם כלל ובאו בברית ונמולו, ואולי ישובו אל ה' ויהיו כולם בכלל אנשי בית אברהם, ומן הנפש אשר עשו בחרן. ועוד חרה לו, שלא יאמרו כי בעצתו נעשה הדבר, ויהיה חילול השם שיעשה הנביא חמס ושוד. וזה טעם (בראשית מט ו): "בסודם אל תבא נפשי" - התנצלות שלא היה בסודם בענותם במרמה, ובקהלם לא נתיחד כשבאו על העיר והרגום. ולכן יקלל (בראשית מט ז): "אפם ועברתם". וכן תרגם אונקלוס: "ברזיהון לא הות נפשי באיתכנשיהון למהך וכו'".
@32 וטעם (בראשית מט ו): "כי באפם הרגו איש וברצונם עקרו שור" - שעשו החמס באפם שכעסו על שכם, וברצונם שהם חפצים בו, לא פשע המומתים ולא חטאתם.
@32 ואמר אונקלוס, כי טעם שוֹר כמו שוּר בשורק, מן (בראשית מט כב): "בנות צעדה עלי שור", ותרגם בו עוד "סנאה", מן (תהלים צב יב): "ותבט עיני בשורי". והטעם, שעקרו עיר מוקפת חומה, את טפם ואת נשיהם, אחרי הרגם אנשיה. ויהיה "עקרו" מן (צפניה ב ד): "ועקרון תעקר".
@32 ואחרים פירשו (רד"ק בשם ריב"א), כי שור גדול בבהמות, רמז לחמור ושכם בנו נשיא הארץ, כמו (דברים לג יז): "בכור שורו הדר לו", (עמוס ד א): "פרות הבשן אשר בהר שומרון". וכן יכנו הכתובים השרים הגדולים באילים ועתודים.
@32 והנכון בעיני, שהכתוב כמשמעו, אמר כי "באפם הרגו" כל "איש" באפם, "וברצונם", אחרי ששככה חמתם בהריגת האנשים, "עקרו" כל "שור", רמז למקניהם וקנינם כל אשר בבית וכל אשר בשדה. והזכיר זה, לומר, כי בסודם לא באה נפשו בכל אלה, אפילו לעקור להם מקנה וקנין ולבוז שללם כלל. ו"עקרו" מן (יהושע יא ו): "ואת סוסיהם תעקר". אך הכל לשון אחד וענין אחד.
@32 {ו} **וטעם כי באפם הרגו איש וברצונם עקרו שור** . שעשו החמס באפם שכעסו על שכם וברצונם שהם חפצים בו לא פשע המומתים ולא חטאתם ואמר אונקלוס כי טעם שור כמו שור בשורק מן בנות צעדה עלי שור (להלן פסוק כב) ותרגם בו עוד סנאה מן ותבט עיני בשורי (תהלים צב יב) והטעם שעקרו עיר מוקפת חומה את טפם ואת נשיהם אחרי הרגם אנשיה ויהיה "עקרו" מן ועקרון תעקר (צפניה ב ד) ואחרים פירשו (רד"ק בשם ריב"א) כי שור גדול בבהמות רמז לחמור ושכם בנו נשיא הארץ כמו בכור שורו הדר לו (דברים לג יז) פרות הבשן אשר בהר שומרון (עמוס ד א) וכן יכנו הכתובים השרים הגדולים באילים ועתודים והנכון בעיני שהכתוב כמשמעו אמר כי באפם הרגו כל איש באפם וברצונם אחרי ששככה חמתם בהריגת האנשים עקרו כל שור רמז למקניהם וקנינם כל אשר בבית וכל אשר בשדה והזכיר זה לומר כי בסודם לא באה נפשו בכל אלה אפילו לעקור להם מקנה וקנין ולבוז שללם כלל ו "עקרו" מן ואת סוסיהם תעקר (יהושע יא ו) אך הכל לשון אחד וענין אחד
@33 ...ובעבור זה (בראשית מט ז): "יחלקם ביעקב", שלא יוסדו; "ויפיצם בישראל", שלא יקהלו, ויהי להם כן, כי נחלת שמעון בתוך בני יהודה, כדכתיב (יהושע יט א): "ויהי נחלתם בתוך נחלת בני יהודה", והיו עריהם מחולקות זו מזו בכל שבט יהודה, ונחלת לוי, ערי מקלט, מנופצות בכל ישראל.
@36 אין ענינו שלא יסור לעולם, כי כתוב (דברים כח לו): "יולך ה' אותך ואת מלכך אשר תקים עליך אל גוי אשר לא ידעת אתה ואבותיך", והנה הם ומלכם בגולה, אין להם עוד מלך ושרים, וימים רבים אין מלך בישראל, והנביא לא יבטיח את ישראל שלא ילכו בשבי בשום ענין בעבור שימלוך עליהם יהודה.
@36 אבל ענינו, שלא יסור שבט מיהודה אל אחד מאחיו, כי מלכות ישראל המושל עליהם ממנו יהיה, ולא ימשול אחד מאחיו עליו. וכן לא יסור "מחוקק מבין רגליו", שכל מחוקק בישראל אשר בידו טבעת המלך, ממנו יהיה, כי הוא ימשול ויצוה בכל ישראל, ולו חותם המלכות, "עד כי יבא שילה ולו יקהת כל העמים" לעשות בכולם כרצונו, וזהו המשיח, כי:
@36 "השבט" ירמוז לדוד שהוא המלך הראשון אשר לו שבט מלכות,
@36 ו"שילה" הוא בנו אשר לו יקהת העמים.
@36 ולא יתכן מאמר רבי אברהם, שיהיה שילה דוד, כי לא היה ליהודה שבט קודם דוד, כי אף על פי ששבטו נכבד ונוסע בתחלה, אין שבט רק למלך ומושל, כדכתיב (תהלים מה ז): "שבט מישור שבט מלכותך", (ישעיהו יד ה): "שבט מושלים", (יחזקאל יט יד): "שבט למשול".
@36 והכתוב הזה רמז, כי יעקב המליך שבט יהודה על אחיו, והוריש ליהודה הממשלה על ישראל, והוא מה שאמר דוד (דברי הימים א כח ד): "ויבחר ה' אלהי ישראל בי מכל בית אבי להיות למלך על ישראל לעולם כי ביהודה בחר לנגיד ובבית יהודה בית אבי ובבני אבי בי רצה להמליך על כל ישראל".
@36 ואמר "לא יסור" לרמוז, כי ימלוך שבט אחר על ישראל, אבל מעת שיחל להיות ליהודה שבט מלכות, לא יסור ממנו אל שבט אחר, וזהו שנאמר (דברי הימים ב יג ה): "כי ה' אלהי ישראל נתן ממלכה לדוד על ישראל לעולם לו ולבניו".
@36 וענין שאול היה, כי בעבור שדבר שאלת המלכות בעת ההיא נתעב אצל הקדוש ברוך הוא, לא רצה להמליך עליהם מן השבט אשר לו המלכות שלא יסור ממנו לעולמים, ונתן להם מלכות שעה, ולזה רמז הכתוב שאמר (הושע יג יא): "אתן לך מלך באפי ואקח בעברתי", שנתנו לו שלא ברצונו, ולכן לקחו בעברתו, שנהרג הוא ובניו ונפסקה ממנו המלכות. והיה כל זה מפני שהיה שמואל שופט ונביא ולוחם מלחמותיהם על פי ה' ומושיע אותם, ולא היה להם לשאול מלך בימיו, כמו שאמר להם (שמואל א יב יב): "וה' אלהיכם מלככם". והקב"ה אמר לו (שמואל א ח ז): "לא אותך מאסו כי אותי מאסו ממלוך עליהם", ולפיכך לא נתן להם מלכות של קיימא.
@36 ומה שאמר הכתוב (שמואל א יג יג): "נסכלת לא שמרת את מצות ה' אלהיך אשר צוך כי עתה הכין ה' את ממלכתך אל ישראל עד עולם", שאם לא חטא, היה לזרעו מלכות בישראל, לא על כלם, וזה טעם "אל ישראל"; אולי היה מולך על שבטי אמו, על בנימן ואפרים ומנשה, כי יהודה ואפרים כשני עממים נחשבים בישראל; או היה מלך תחת יד מלך יהודה.
@36 ולפי דעתי, היו המלכים המולכים על ישראל משאר השבטים אחרי דוד עוברים על דעת אביהם ומעבירים נחלה, והם היו סומכים על דבר אחיה השילוני הנביא שמשח לירבעם ואמר (מלכים א יא לט): "ואענה את זרע דוד למען זאת אך לא כל הימים", וכאשר האריכו ישראל להמליך עליהם משאר השבטים מלך אחר מלך, ולא היו חוזרים אל מלכות יהודה, עברו על צוואת הזקן ונענשו בהם, וכמו שאמר הושע (הושע ח ד): "הם המליכו ולא ממני".
@36 וזה היה עונש החשמונאים, שמלכו בבית שני, כי היו חסידי עליון, ואלמלא הם נשתכחו התורה והמצות מישראל, ואף על פי כן נענשו עונש גדול, כי ארבעת בני חשמונאי הזקן החסידים המולכים זה אחר זה, עם כל גבורתם והצלחתם, נפלו ביד אויביהם בחרב, והגיע העונש בסוף למה שאמרו רז"ל (בבא בתרא ג א): "כל מאן דאמר מבית חשמונאי קאתינא עבדא הוא", שנכרתו כלם בעון הזה. ואף על פי שהיה בזרע שמעון עונש מן הצדוקים, אבל כל זרע מתתיה חשמונאי הצדיק לא עברו אלא בעבור זה שמלכו ולא היו מזרע יהודה ומבית דוד, והסירו השבט והמחוקק לגמרי, והיה עונשם מדה כנגד מדה, שהמשיל הקדוש ברוך הוא עליהם את עבדיהם והם הכריתום.
@36 ואפשר גם כן שהיה עליהם חטא במלכותם מפני שהיו כהנים, ונצטוו (במדבר יח ז): "תשמרו את כהונתכם לכל דבר המזבח ולמבית לפרכת ועבדתם עבודת מתנה אתן את כהונתכם", ולא היה להם למלוך, רק לעבוד את עבודת ה'. וראיתי בירושלמי במסכת הוריות (ירושלמי הוריות פרק ג הלכה ב): "אין מושחין מלכים כהנים. אמר רבי יהודה ענתוריא על שם לא יסור שבט מיהודה. אמר רבי חייא בר' אבא למען יאריך ימים על ממלכתו הוא ובניו בקרב ישראל, מה כתיב בתריה לא יהיה לכהנים הלוים". הנה, שנו בכאן שאין מושחין מלכים מן הכהנים בני אהרן. ופירש תחלה שהוא לכבוד יהודה, שאין השררה סרה מן השבט ההוא. ולפיכך, אף על פי שישראל מקימים עליהם מלך משאר השבטים כפי צורך השעה, אין מושחים אותן שלא יהיה עליהם הוד מלכות אלא כמו שופטים ושוטרים יהיו. והזכירו הכהנים, שאף על פי שהן בעצמן ראויים למשיחה, אין מושחין אותן לשם מלכות, וכל שכן שאר השבטים, וכמו שאמרו בגמרא (הוריות יא) שאין מושחין אלא מלכי בית דוד. ורבי חייא בר אבא פירש, שהוא מנוע מן התורה שלא יהיה לכהנים הלוים כל שבט לוי חלק ונחלה במלכות, והוא דבר ראוי והגון.
@36 "אסיפת העמים, שנאמר (ישעיהו יא י): "אליו גוים ידרשו". ודומה לו (משלי ל יז): "עין תלעג לאב ותבוז ליקהת אם", לקבוץ קמטים שבפניה מפני זקנתה. ובתלמוד (יבמות קי א): "דמקהו קהיאתא בשוקא דנהרדעא". ויכול לומר קהיית עמים", לשון רש"י.
@36 ואינו נראה לפרש ב"יקהת אם" אסיפת אם.
@36 ולשון "מקהו קהיאתא" אינו אלא לשון פירכות וקושיות שהיו מקשים ומפרכים בה קושיות הרבה, כי המתקשה בדבר יקרא "קוהה" בלשון חכמים, כמו שאמרו במדרש חזית (שיר השירים רבה ג ח) "כולם אחוזי חרב" - שהיו כולם שונים הלכה כחרב, שאם בא מעשה אל ידיהם לא תהא הלכה קוהה להם, וכן עוד שם רבים. וממנו אמרו בגמרא (נזיר סה ב): "ר' יהושע קיהה וטהר", שהקשה בו דברים רבים ושבר כל דברים המטמאים עד שטיהר בהכרח. וכן מצינו בנוסחאות ישנות בגמרא (בבא מציעא נב א): "מאן דקהי אזוזי מיקרי נפש רעה", שמדקדק בו ומתקשה לקבל אותו מחבירו.
@36 ובעלי הדקדוק (הרד"ק ור' יונה בן ג'נאח) אומרים ב"יקהת" ששרשו יקה, ופירשו בו לשון משמעות וקבול המצוה, "יקהת עמים" - שישמעו אליו ויעשו כל אשר יצוה עליהם; "תבוז ליקהת אם" - לקבל מצותה.
@36 והנכון בעיני, שהוא מלשון (ירמיהו לא כט): "האוכל הבוסר תקהינה שניו", ושרשו קהה, והיו"ד בו כיו"ד יצהר, וענין כלם החולשה והשבירה: יאמר שלא יסור שבט נוגש מיהודה, עד שיבא בנו אשר לו חולשת העמים ושבירתם, שיחליש את כלם לפי חרב. וכן (קהלת י י): "אם קהה הברזל", שנחלש ואינו יכול לכרות, כסכין שעמדה בלשון חכמים (ביצה כח), או שנשבר קצת ונעשו בו פגימות. וכן מצאתי עוד שם במדרש חזית (שיר השירים רבה א יב): "הופיע להם הקב"ה ריח טוב מבשמי גן עדן, והיתה נפשם קוהה לאכול, אמרו לו "רבינו משה תן לנו מה נאכל!" אמר להם "כך אמר לי הקב"ה כל בן נכר לא יאכל בו", עמדו והפרישו הנכרים מביניהם והיתה נפשם קוהה לאכול וכו'". והענין, שהיתה נפשם נחלשת ומשתברת בגופם מרוב תאותם לאכול מן הפסח, שנדבק בו הריח הטוב. וכן "לא תהא הלכה קוהה להם" - נחלשת ורופפת בידם. ו"מקהו קהיאתא" - מקשים קושיות מחלישות הנפש מרוב הצער והעיון, או הוא לשון שמשברין ומפרכין, כלשון (קידושין יג ב): "פריך רב אחא". וכך אמרו (מכילתא בא יח) "אף אתה הקהה את שניו" - שבר אותם או תחלישם בדבריך, כי הבוסר מחליש ואינו משבר, אלא שהחלישות והשבירה ענין שוה, והקהיה תכלול את שניהם.
@38 **חכלילי עינים** . אמרו המפרשים (רש"י ראב"ע והרד"ק) שהוא ענין אדמימות שיתאדמו עיניו מרוב שתית יין וכמוהו למי חכלילות עינים (משלי כג כט) והנראה בעיני שהוא הפוך מן כחלת עיניך (יחזקאל כג מ) ונכפלה בו הלמ"ד כמנהג רבים והוא כענין מכחול העינים הידוע ומורגל בדברי רבותינו (כלים פי"ג מ"ב) וכן שמו בערבי "אל כחול" יאמר שהוא כחול העינים מן היין כי כאשר אחרים כוחלים אותם בפוך שהוא ה"אל כחול" כן יכחול אותם הוא ביין וכמו שהאחרים מלבנים שיניהם בתמרוקים כן ילבן אותם בחלב והמשל לרבוי היין והחלב בארצו כאשר הזכיר אונקלוס וכן למי חכלילות עינים (משלי כג כט) כמו כחלילות יאמר שעיניו כחולות ביין ולא יוכל להסתיר שכרותו או יאמר למי חכלילות עינים שיצטרך לכחול עיניו תמיד למאחרים על היין כי היין יחשיך את עיניהם ויורידו דמעה ותמקנה בחוריהן ויצטרך שיהיו עיניו במכחול תדיר יספר הכתוב בגנות היין ברעות הבאות לו מבחוץ במדנים ובפצעים ושישמע בביתו אוי ואבוי ויזכיר הנזק ההוא ההוה לו ממנו בגופו חשכת עיניו ותחלואיהם הרבים וזה פירוש וענין נכון
@42 **דן ידין עמו** . כמו כי ידין ה' עמו (דברים לב לו) ארי ידין ה' דינא דעמיה כלשון שפטני ה' וריבה ריבי מגוי לא חסיד (תהלים מג א) ריב אלמנה (ישעיהו א יז) יאמר כי דן ינקום נקמת עמו כל שבטי ישראל כאחד והטעם כי פלשתים הרעו לכל ישראל כמה פעמים כי בימי שמגר בן ענת החלו (שופטים ג לא) ובימי יפתח כתוב (שם י ז) וימכרם ביד פלשתים וגם אחרי עבדון בן הילל (שם יב יג) ויתנם ה' ביד פלשתים ארבעים שנה (שם יג א) ולא היה בשופטים מי שהכניעם או שנצחם כלל ואף על פי שכתוב בשמגר (שם ג לא) ויך את פלשתים שש מאות איש במלמד הבקר איננה נקמה כי איננה מכה רבה על כן כתוב בשמשון (שם יג ה) והוא יחל להושיע את ישראל מיד פלשתים ולקח נקמת ישראל מהם כי הרג מהם עם רב וכל סרני פלשתים המית והזכיר ידין כי היה הנוקם הזה שופט לא מלך ואפשר שזה דעת אונקלוס שאמר ביומוהי יתפרק עמיה ויתכן שיהיה כאחד שבטי ישראל כמיוחד שבשבטים הוא יהודה שנאמר בו (לעיל פסוק ח) ידך בעורף אויביך כי גם זה יגבר על אויביו וינצחם
@43 **שפיפון** . שם לנחש שישוף עקב ונכפלה בו העי"ן ואמרו בירושלמי במסכת תרומות (פ"ח מ"ג) מין קטן הוא ושפיפון שמו ודומה לשערה ונתנה רשות לארץ ליבקע מפניו ודמה שמשון לנחש בעבור שלא היה שמשון בא על אויביו במלחמה כאשר השופטים או המלכים רק הוא לבדו יוצא עליהם כמו צפעוני היוצא ממאורתו על הולכי דרך או המין הקטן שבנחשים שאינו ניכר כלל להולכי ארח וטעם הנושך עקבי סוס רמז לשני העמודים אשר הבית נכון עליהם (שופטים טז כט) ושלשת אלפים אשר על הגג (שם פסוק כז) הם הרוכב הנופל אחור כאשר ישוך הנחש בעקבי הסוס יגביה הסוס ראשו ורגליו הראשונים ויפול רוכבו אחור
@44 **לישועתך קויתי ה'** . לא היה בכל שופטי ישראל מי שנפל ביד אויביו זולתי שמשון שהוא הנחש הזה כדכתיב (שופטים ב יח) והיה ה' עם השופט והושיעם מיד אויביהם כל ימי השופט והוא היה האחרון לשופטים כי שמואל נביא היה ולא נלחם להם ובימיו מלכו המלכים וכאשר ראה הנביא תשועת שמשון כי נפסקה אמר לישועתך קויתי ה' לא לישועת נחש ושפיפון כי בך אושע לא בשופט כי תשועתך תשועת עולמים
@45 **גד גדוד יגודנו** . פירש רש"י על דרך אונקלוס יתנבא כי גדוד יגוד ממנו ואותו הגדוד יגוד עקב על עקבו שיחזור לדרך אשר בא לו לשלום אל ארצו והנכון שיהיה כמו לעלות לעם יגודנו (חבקוק ג טז) יאמר כי גדוד יגודנו תמיד שיהיו לו מלחמות רבות ופשט גדוד עליו בארצו והוא יגוד אותו על עקיבו שיתגבר עליו וירדוף אותו והם ישובו על עקב בשתם שבח אותם בגבורה ונצוח כל הבאים עליהם למלחמה וזה כענין ברכת משה רבינו בהם (דברים לג כ) ברוך מרחיב גד כלביא שכן בעבור שירש ארץ רחבת ידים וגדולה מאד והיא בעבר הירדן היו באים עליהם תמיד גדודי עמון ומואב שכניו הרעים התובעים בנחלה ופושטים עליהם והוא כלביא שכן על טרפו מקולם לא יירא ומהמונם לא ייחת וזה פירוש נאה למדתיו מן הירושלמי שאמרו במסכת סוטה (פ"ח ה"י) גד גדוד יגודנו גייסא אתי מגיסתא והוא מגייס לה לומר כי הגייס יבא לאסוף חיל ולגייס עליו והוא יגוד עליהם ויביא גדודיו בארצם ואולי ירמוז הנביא על מלחמת יפתח הגלעדי עם בני עמון כי בני גד ירשו כל ערי הגלעד וחצי ארץ בני עמון והיו בני עמון תמיד נלחמים באנשי גלעד והוא כמעט עבר עליהם והכה אותן ואת עריהן מכה גדולה מאד (שופטים יא לג) והיה הענין ההוא נס גדול הזכירו הנביא כאשר הזכיר דבר שמשון
@47 **נפתלי אילה שלוחה** . מנהג במושלי ארץ לשלוח זה לזה האילים וכך הענין כי האילות שנולדו בארץ מלך הצפון יגדלו אותן בהיכלי מלך הנגב ויקשרו כתב הבשורה בקרניה והיא תרוץ מהר ותשוב למעונה ויתבשרו בהן וזה טעם אמרי שפר כלומר אילה שלוחה מבשר בשורות טובות והענין הזה ידוע והוא מוזכר בירושלמי במסכת שביעית (פ"ט ה"ב) אמרו אין אזלין לון חזרין ואי בעית למבדקיה אייתו טביין וישלחון לארע רחיקא בסוף אינון חזרין עבד כן ואייתי טביין וחפי קרניהון בכסף ושלחון לאפריקי ובסוף תלת עשרה שנין חזרון לאתריהון שהתירום לאחר י"ג שנה ומיד חזרו והמשל כי נפתלי שבע רצון ומלא כל טוב וממנו תבא בשורה לכל ישראל כי עשתה ארצו פירות לשבעה כמו שהזכירו רבותינו בפירות גנוסר (תנחומא ויחי יג)
@48 **בן פורת יוסף** . בן חן והוא לשון ארמי (ב"מ קיט) אפריון נמטיה לרבי שמעון בן פורת עלי עין חנו נטוי על העין הרואה אותו לשון רש"י ורחוק הוא מאד לסמכו אל הלשון ההוא שלשונות כאלה בתלמוד יוני או פרסי ושאר לשונות אין להם חבר בלשון הקדש ועוד כי לפי הנמצא ממנו איננו רק לשון ברכה ושבח והנו"ן בו שרש וכן בבראשית רבה (ס יג) ויברכו את רבקה דוויין ושפופין ולא היו מפרנין אלא בפה ודומה לי שהוא ממה שאמרו (כתובות נד) פורנא ליתמי שפירושו השבח שהשביחו הוא ליתומים וקראו עוד הכתובה פורנא אשה גובה פורנא מהם (שם סז) הכתובה שהיא שבח בית אביה וכמו שאמרו (ב"ר פ ז) מהר פראנון אבל בן פורת או כדעת אונקלוס מלשון פוריה ועניפה או כדברי בעלי הדקדוק (עיין ספר השרשים שורש בנה) שעשו פורת מלשון ותארכנה פארותיו (יחזקאל לא ה) והם אמרו כי בן כמו נטע והביאו לו דומה (תהלים פ טז) וכנה אשר נטעה ימינך ועל בן אמצתה לך והענין כאלו אמר נטע שבו פארות רבות יוסף ועל דעתי בן כמשמעו יאמר כי יוסף הוא בן שהוא כמו פארות אילן שתול על המעין אשר לא יכזבו מימיו ועשתה בנות צעדה אותן על החומות הגבוהות בשמים וכנה הבדים אשר תצאנה מן פארה בבנות כי הן בנות לפארות הגדולות והוא דרך צחות לבן פורת ולא נסמך בן אל פורת אבל הוא כמו אשור ארז בלבנון (יחזקאל לא ג) נפתלי אילה שלוחה (לעיל פסוק כא) בנימין זאב (להלן פסוק כז) ולפיכך נקוד בצרי כי אילו היה פירושו נטע שיש לו פארות משפטו בסגול ואמר "בן" דרך חבוב כמו מטרף בני עלית ועל הכלל ראוי שנפרש בברכת יוסף שיהיה בה זכר לשני השבטים היוצאים ממנו והוא לשון פורת ובנות אבל מפני שהזכיר לוי ושבטי ישראל אינם אלא שנים עשר לא יעשה ממנו כן בברכתו שנים שבטים חלוקים אבל ירמוז להם וכן במשה רבינו בברכתו דמה אותו לשור ולראם (דברים לג יז) והזכיר בו הקרנים כי כל אחד מהם גוף אחד שממנו יתחלקו קרנים ובעבור ששם לא הזכיר שמעון אמר בפירוש והם רבבות אפרים והם אלפי מנשה (שם)
@50 **מידי אביר יעקב** . זאת היתה לו מאת הקב"ה שהוא אביר יעקב ומשם זכה להיות רועה אבן ישראל עיקרן של ישראל לשון האבן הראשה לשון רש"י מאל אביך היתה זאת לך והוא יעזרך ועם הקב"ה היה לבך כשלא שמעת לדברי אדונתך והוא יברכך גם זה לשונו ורבי אברהם אמר כי מ"ם מאל אביך נמשך לואת שדי והוא יברכך ועל דרך האמת הברכה הזאת דומה לברכה אשר ברך למעלה את הנערים כי אביר יעקב הוא אלהי אמת ולא בא בכתוב אביר אברהם או יצחק וזולתם רק אביר יעקב או אביר ישראל (ישעיהו א כד) הוא יעקב והנה מידי אביר יעקב הגדולה והגבורה משם מידי אביר יעקב רועה אבן ישראל היא האבן הראשה שהיתה לראש פינה (תהלים קיח כב) מאת ה' ונקרא אבן ישראל כמו שאמרו חכמים כנסת ישראל היא האבן הראשה וטעם אבן שהוא בנין משלים הכל וענין רועה כי העוז בגבורה מתעלה בימינו של הקב"ה כדכתיב (חבקוק ג ד) קרנים מידו לו ושם חביון עזו כלומר ושם בימינו חביון העוז וחביון הוא הכח המתעלה הנחבא במקום אצילותו וזהו שנאמר (תהלים פ טז) וכנה אשר נטעה ימינך מאל אביך האלהים הרועה אותי מעודי ואת שדי ויברכך ודעת הברכה כי מידי אביר יעקב מחסד שרועה אבן ישראל ומאלהי אביו יפיק רצון ויבא עזרו ועם שדי תהיה ברכתו והנה הוא מבורך בשמים ובארץ וזה טעם ברכות אביך גברו על ברכת הורי כי הבנין שלם בו כך העליתי הענין הזה ממדרשו של רבי נחוניא בן הקנה (עיין ספר הבהיר קצג קמח) והמשכיל יבין
@55 **קברו אותי אל אבותי** . עם אבותי לשון רש"י ולא פירש אל המערה ואיננו עם ויתכן שיהיה לשון המקרא הזה קצר קברו אותי ושאוני אל אבותי אל המערה כי כן אמר (לעיל מז ל) ונשאתני ממצרים וישאו אותו בניו (להלן נ יג) ויתכן שישמש "אל" בפנים רבים קברו אותי עם אבותי כמו ואשה אל אחותה לא תקח (ויקרא יח יח) עם אחותה אל המערה במערה כמו ואל הארון תתן את העדות (שמות כה כא) הנה הוא נחבא אל הכלים (שמואל א י כב) וכן (לעיל כג יט) ואחרי כן קבר אברהם וגו' אל מערת ואמר רבי אברהם כי טעם קברו אותי אל אבותי שילכו עם יוסף ולא היה יעקב צריך לכך אבל צוה לכולם עתה שיקברו אותו אל המערה כאשר השביע ליוסף כי פחד אולי לא יתן פרעה רשות ליוסף לצאת מן הארץ שלא יתעכב בארצו והלא תראה שהוצרך יוסף לחלות פני בית פרעה שיבקשו עליו מפרעה שילך והוא ענה כאשר השביעך כי בעבור השבועה יתרצה בזה
@57 **וטעם שמה קברו את יצחק** . שלא אמר קברתי בעבור היות עשו עמו בקבורת אביהם ולא ירצה עתה להזכירו ועוד שלא יצטרך עתה להאריך לאמר שמה קברנו את יצחק ושמה קברו את רבקה אשתו כי לא היה הוא בקבורת אמו והזכיר להם בצואתו המערה והנקברים בה לגדל המקום כדי שיזדרזו לקברו שם ואמר אשר קנה אברהם את השדה לאחוזת קבר להודיע כי אברהם צוה שיהיה המקום ההוא בית הקברות להם לאחוזת עולם אבל למטה (נ יג) כשאמר ויקברו אותו במערת שדה המכפלה אשר קנה אברהם לאחזת קבר נתכוון הכתוב לרמוז כי ביעקב נשלמה כונת הצדיק כי לשלשתם קנאה ולא יקברו בה עוד איש ועל כן לא צוה יוסף שיקברו אותו במערה עם אבותיו וראיתי במכילתא לרבי שמעון בן יוחאי (בשלח יט) שאמר להם יוסף וכשאתם מעלין אותי קברו אותי בכל מקום שתרצו מקובל אני שאיני נכנס לקבורת אבותי שאין נכנס לקבר אבות אלא שלשה אבות ושלש אמהות שנאמר שמה קברו את אברהם וגו' ואומר (להלן נ ה) בקברי אשר כריתי לי בי הוא פוסק ויתכן שרמז להם באמרו ושמה קברתי את לאה שכבר החזיק הוא במערה ואמר זה כנגד עשו שלא יערער הוא ובניו בקבורתו לטעון שהמערה שלו כי הוא הבכור והוא הראוי להקבר עם אבותיו ואף על פי שהלך אל ארץ אחרת יהיו נושאים אותו משם כאשר ישאו בניו את יעקב כי ירצה להקבר עם אבותיו הקדושים וליחד אתם בקבורה ואם יקבר שם עשו לא יקבר שם יעקב כי אין לשתי משפחות בית קבורה אחד וזהו גם כן מה שאמר בקברי אשר כריתי לי שכבר כרה לו הקבר להחזיק בו וזה טעם ויעל עמו גם רכב גם פרשים (להלן נ ט) כי ידע זדון עשו ובניו וכן היה מעשה כי מצינו בספר דברי הימים ליוסף בן גוריון (הוא ספר יוסיפון) וזולתו מספרי הקדמוניות כי בא צפו בן אליפז בן עשו ועשה עמהם קטטה על זה עד שערכו מלחמה ותגבר יד יוסף ותפשו עם מבחר גדודיו והביאום למצרים ועמד שם בתפיסה כל ימי יוסף וברח משם במותו והלך לארץ כאנפנייא ומלך על כתים ברומא ובסוף הומלך על כל ארץ איטלייא והוא אשר מלך ראשון על רומה והוא אשר בנה ההיכל הראשון והגדול מאשר נבנו ברומה וגם רבותינו (סוטה יג) הזכירו מזה הענין מקטטת עשו במערה והכתוב שאמר בכאן (להלן נ יד) וישב יוסף מצרימה הוא ואחיו וכל העולים אתו לקבור את אביו אחרי קברו את אביו בא לרמוז שלא מת אחד מכלם במלחמה ולא בדרך שעמד להם זכות הנביא וזכות יוסף שעלו עמו ולא צוה יוסף כאשר צוה אביו לשאת אותו לקברו בארץ עתה כי לא יניחוהו בית פרעה כי לכבוד הוא להם ועוד שאם ילכו עמו אחיו ובית אביו יגזלו ויגנבו אנשי הארץ את כל אשר להם ואיננו דרך כבוד שיוליכוהו שם אחרים
@57 "ויאמר יוסף אל אחיו אנכי מת" - (שם פסוק כד) כי אחיו חיים היו כי האריכו ימים יותר ממנו כאשר אתה רואה בלוי ואמר (שם פסוק כה) וישבע יוסף את בני ישראל כי בראותו שאחיו זקנים השביע כל בניהם וכל בית אביו שיצוו גם את בני בניהם לעת הגאולה כי כלם יודעים הגלות
@59 **ויגוע ויאסף** . ומיתה לא נאמרה בו ואמרו רבותינו (תענית ה) יעקב אבינו לא מת לשון רש"י ולדעת רבותינו הרי יעקב הזכיר מיתה בעצמו (לעיל מח כא) הנה אנכי מת והיה אלהים עמכם ואולי לא ידע הוא בנפשו או שלא רצה לתת כבוד לשמו וכן (להלן נ טו) ויראו אחי יוסף כי מת אביהם כי להם מת הוא או שלא ידעו הם בזה כלל וענין המדרש הזה כי נפשות הצדיקים צרורות בצרור החיים וזו תחופף עליו כל היום לובשת לבושה השני שלא יפשטנה ערומה כיעקב או תתלבש לעתים מזומנות ויובן הענין הזה במסכת שבת (קנב) ובמסכת כתובות (קג.)
@59 **ונשלם ספר בראשית בספור דברי האבותלהגיד ראשונות וחדשות בטרם תצמחנה בלבבותוליוצר כל ראשית רוכב ערבות תהלות רבות והודאות לרבבותולו נתכנו עלילות וסבות מגלה עמוקותודעות נשגבות ומוציא לאור המחשבותהמוליך אותי בדרך צדקה בתוך נתיבות הגומל לחייבים טובותתם ונשלם שבח לבורא עולם חסלת פרשת ויחי** אבן עזרא **ויאסף רגליו אל המטה** . כי בתחלה ישב על המטה ורגליו תלויות כמנהג ארץ אדום היום ולא כן מטות הישמעאלים:
